/* Long-answer bank: Course notes Chapter 1 (examples, exercises, end of section and end of chapter problems).
   Source: D. Wolczuk, Calculus for the Sciences (CC BY-NC 4.0), with the official exercise and problem solutions.
   Generated from the catalogue in work/notes/coursenotes_ch1.md. */
M127.addLongAnswer([
  {id:"CN1.1.1-EX1", src:"Course notes 1.1, Example 1", lec:"L01", kind:"example", page:"p. 2",
   q:"Determine the derivative of $f(x) = 3x^2 + e^x + 2$.",
   sol:[
    "Using the Sum Rule,",
    "$f'(x) = 6x + e^x + 0 = 6x + e^x$"],
   ans:"$f'(x) = 6x + e^x$"},
  {id:"CN1.1.1-EX2", src:"Course notes 1.1, Example 2", lec:"L01", kind:"example", page:"p. 2",
   q:"Determine the second derivative of $g(x) = (x^3+x)\\cos(x)$.",
   sol:[
    "Using the Product Rule,",
    "$g'(x) = (3x^2+1)\\cos(x) - (x^3+x)\\sin(x)$",
    "Using the Product Rule on each term,",
    "$g''(x) = \\big[6x\\cos(x) - (3x^2+1)\\sin(x)\\big] - \\big[(3x^2+1)\\sin(x) + (x^3+x)\\cos(x)\\big]$",
    "$g''(x) = (-x^3+5x)\\cos(x) - (6x^2+2)\\sin(x)$"],
   ans:"$g''(x) = (-x^3+5x)\\cos(x) - (6x^2+2)\\sin(x)$"},
  {id:"CN1.1.1-EX3", src:"Course notes 1.1, Example 3", lec:"L01", kind:"example", page:"p. 2",
   q:"Determine the derivative of $h(x) = \\dfrac{3x^2+x}{x-1}$.",
   sol:[
    "Using the Quotient Rule,",
    "$h'(x) = \\dfrac{(6x+1)(x-1) - (1-0)(3x^2+x)}{(x-1)^2}$",
    "$h'(x) = \\dfrac{3x^2-6x-1}{(x-1)^2}$"],
   ans:"$h'(x) = \\dfrac{3x^2-6x-1}{(x-1)^2}$"},
  {id:"CN1.1.1-EX4", src:"Course notes 1.1, Example 4", lec:"L01", kind:"example", page:"p. 3",
   q:"Determine the derivative of $j(s) = (s^2+\\sin(s))^{1/3}$.",
   sol:[
    "Using the Chain Rule,",
    "$j'(s) = \\frac{1}{3}(s^2+\\sin(s))^{-2/3}\\cdot(2s+\\cos(s))$"],
   ans:"$j'(s) = \\frac13 (s^2+\\sin(s))^{-2/3}(2s+\\cos(s))$"},
  {id:"CN1.1.1-XR1", src:"Course notes 1.1, Exercise 1", lec:"L01", kind:"exercise", page:"p. 3",
   q:"Determine the derivative of each function.<br>(a) $f(x) = x^3 + \\dfrac{7}{x}$<br>(b) $f(x) = 5\\sqrt[3]{x+1}$<br>(c) $f(x) = e^x\\cos(x)$<br>(d) $g(r) = \\sin^2(r)$<br>(e) $h(w) = e^{\\sqrt{w}}$<br>(f) $j(t) = \\dfrac{e^t\\sin(t)}{t^2}$",
   sol:[
    "(a) Write $\\frac7x = 7x^{-1}$. By the Sum Rule, $f'(x) = 3x^2 - \\dfrac{7}{x^2}$",
    "(b) By the Chain Rule, $f'(x) = 5\\cdot\\frac13(x+1)^{-2/3}\\cdot(1+0) = \\frac53(x+1)^{-2/3}$",
    "(c) By the Product Rule, $f'(x) = e^x\\cos(x) - e^x\\sin(x)$",
    "(d) By the Chain Rule, $g'(r) = 2\\sin(r)\\cos(r)$",
    "(e) By the Chain Rule, $h'(w) = e^{\\sqrt w}\\cdot\\frac12 w^{-1/2} = \\dfrac{e^{\\sqrt w}}{2\\sqrt w}$",
    "(f) By the Quotient Rule and the Product Rule,",
    "$j'(t) = \\dfrac{[e^t\\sin(t)+e^t\\cos(t)]t^2 - 2t\\,e^t\\sin(t)}{t^4} = \\dfrac{[e^t\\sin(t)+e^t\\cos(t)]t - 2e^t\\sin(t)}{t^3}$"],
   ans:"(a) $f'(x) = 3x^2 - \\frac{7}{x^2}$; (b) $f'(x) = \\frac53(x+1)^{-2/3}$; (c) $f'(x) = e^x\\cos(x) - e^x\\sin(x)$; (d) $g'(r) = 2\\sin(r)\\cos(r)$; (e) $h'(w) = \\frac{e^{\\sqrt w}}{2\\sqrt w}$; (f) $j'(t) = \\frac{[e^t\\sin(t)+e^t\\cos(t)]t - 2e^t\\sin(t)}{t^3}$"},
  {id:"CN1.1.2-EX5", src:"Course notes 1.1, Example 5", lec:"L01", kind:"example", page:"p. 4",
   q:"Assume the mass $M$ of an object in kg given by its radius $r$ in cm is $M(r) = \\dfrac{7r^3+2}{r^2}$. Find the rate of change of the mass with respect to the radius and indicate the units.",
   sol:[
    "By the Quotient Rule,",
    "$\\dfrac{dM}{dr} = \\dfrac{(21r^2+0)(r^2) - 2r(7r^3+2)}{(r^2)^2} = \\dfrac{21r^4 - 14r^4 - 4r}{r^4} = \\dfrac{7r^3-4}{r^3}$",
    "$M$ is in kg and $r$ is in cm, so $\\frac{dM}{dr}$ has units kg/cm."],
   ans:"$\\dfrac{dM}{dr} = \\dfrac{7r^3-4}{r^3}$ kg/cm"},
  {id:"CN1.1.2-EX6", src:"Course notes 1.1, Example 6", lec:"L01", kind:"example", page:"p. 5",
   q:"The velocity of an object in m/s is $v(t) = 3+\\sin(t)$, where $t$ is in seconds. Find the acceleration at any time $t$.",
   sol:[
    "Acceleration is the rate of change of velocity, so $a(t) = v'(t) = 0 + \\cos(t) = \\cos(t)$ m/s$^2$."],
   ans:"$a(t) = \\cos(t)$ m/s$^2$"},
  {id:"CN1.1.2-EX7", src:"Course notes 1.1, Example 7", lec:"L01", kind:"example", page:"p. 5",
   q:"If the number of individuals in a population is $P(t) = 100 + \\frac12 e^t$, where $t$ is in days, find the rate of change of the population with respect to time and indicate the units.",
   sol:[
    "$P'(t) = 0 + \\frac12 e^t = \\frac12 e^t$ individuals/day"],
   ans:"$P'(t) = \\frac12 e^t$ individuals/day"},
  {id:"CN1.1.2-EX8", src:"Course notes 1.1, Example 8", lec:"L01", kind:"example", page:"p. 5",
   q:"The revenue in dollars for producing and selling $x$ thingamajiggers is $R(x) = -0.1x^2 + 10x$.<br>(a) Calculate $R'(10)$ and include its units.<br>(b) Explain the physical meaning of $R'(10)$.",
   sol:[
    "(a) $R'(x) = -0.2x + 10$ dollars/thingamajigger.",
    "Thus $R'(10) = -0.2(10)+10 = 8$ dollars/thingamajigger.",
    "(b) As the units indicate, $R'(10)$ is the approximate change in revenue from producing and selling an eleventh thingamajigger. Revenue goes up by about \\$8 when the company produces and sells eleven instead of ten.",
    "(The actual change is $R(11)-R(10) = 7.9$ dollars, so $R'(10)$ is an approximation.)"],
   ans:"(a) $R'(10) = 8$ dollars/thingamajigger; (b) the 11th thingamajigger adds about \\$8 of revenue",
   note:"The notes say \"profit\" in (b), but $R(x)$ is revenue, so this solution says revenue."},
  {id:"CN1.1.2-XR2", src:"Course notes 1.1, Exercise 2", lec:"L01", kind:"exercise", page:"p. 6",
   q:"The position of a particle for time $t\\ge 0$ in seconds is $s(t) = t^3 - 3t + 1$ m.<br>(a) Calculate $s'(t)$, including its units.<br>(b) Explain the physical meaning of $s'(1)$.",
   sol:[
    "(a) $s'(t) = 3t^2 - 3$ m/s",
    "(b) $s'(1) = 3(1)^2 - 3 = 0$ m/s. It is the instantaneous velocity of the particle at time $t = 1$ s, so at that moment the particle is not moving."],
   ans:"(a) $s'(t) = 3t^2-3$ m/s; (b) $s'(1) = 0$ m/s, the instantaneous velocity at $t=1$ s",
   note:"The official solution interprets $s'(1)$ but does not evaluate it. The value $s'(1)=0$ m/s is added here."},
  {id:"CN1.1.2-XR3", src:"Course notes 1.1, Exercise 3", lec:"L01", kind:"exercise", page:"p. 6",
   q:"Microtubule tips grow and shrink. If $L_0$ is the length (in $\\mu$m) of the tip at $t=0$ and the length at time $t$ (in s) is $L(t) = \\frac{11}{14}t + L_0$ $\\mu$m, what is the growth velocity of the microtubule tip? Indicate the units.",
   sol:[
    "The growth velocity is the rate of change of the length: $v(t) = L'(t) = \\dfrac{11}{14} + 0 = \\dfrac{11}{14}$ $\\mu$m/s."],
   ans:"$v(t) = \\frac{11}{14}$ $\\mu$m/s"},
  {id:"CN1.1.3-EX9", src:"Course notes 1.1, Example 9", lec:"L02", kind:"example", page:"p. 7",
   q:"Find the point-slope equation of the line with slope $m=5$ that passes through the point $(3,-2)$.",
   sol:[
    "Point-slope form: $y = y_0 + m(x-x_0)$.",
    "Substituting $m=5$, $x_0=3$, $y_0=-2$: $y = -2 + 5(x-3)$"],
   ans:"$y = -2+5(x-3)$"},
  {id:"CN1.1.3-EX10", src:"Course notes 1.1, Example 10", lec:"L02", kind:"example", page:"p. 7",
   q:"Find the point-slope equation of the line with slope $m=-2$ that passes through the point $(-1,6)$.",
   sol:[
    "Point-slope form: $y = y_0 + m(x-x_0)$.",
    "Substituting $m=-2$, $x_0=-1$, $y_0=6$: $y = 6 - 2(x-(-1)) = 6-2(x+1)$"],
   ans:"$y = 6-2(x+1)$"},
  {id:"CN1.1.3-XR4", src:"Course notes 1.1, Exercise 4", lec:"L02", kind:"exercise", page:"p. 7",
   q:"Find the point-slope equation of the line with slope $m=-3$ that passes through the point $(-2,1)$.",
   sol:[
    "$y = y_0 + m(x-x_0) = 1 + (-3)(x-(-2)) = 1 - 3(x+2)$"],
   ans:"$y = 1-3(x+2)$"},
  {id:"CN1.1.3-EX11", src:"Course notes 1.1, Example 11", lec:"L02", kind:"example", page:"p. 8",
   q:"Let $f(x) = x^2$. Find the equation of the tangent line to $y=f(x)$ at $a=1$.",
   sol:[
    "$f'(x) = 2x$, so the slope at $a=1$ is $m = f'(1) = 2(1) = 2$.",
    "The tangent line is $y = f(1) + f'(1)(x-1)$",
    "$y = 1^2 + 2(x-1)$",
    "$y = 1 + 2(x-1)$"],
   ans:"$y = 1+2(x-1)$"},
  {id:"CN1.1.3-XR5", src:"Course notes 1.1, Exercise 5", lec:"L02", kind:"exercise", page:"p. 8",
   q:"Let $f(x) = x^3 + x$. Find the equation of the tangent line to $y=f(x)$ at $a=2$.",
   sol:[
    "$f'(x) = 3x^2+1$.",
    "$y = f(2)+f'(2)(x-2) = (2^3+2) + (3(2)^2+1)(x-2)$",
    "$y = 10 + 13(x-2)$"],
   ans:"$y = 10+13(x-2)$"},
  {id:"CN1.1.3-XR6", src:"Course notes 1.1, Exercise 6", lec:"L02", kind:"exercise", page:"p. 8",
   q:"Let $h(x) = e^x$. Find the equation of the tangent line to $y=h(x)$ at $a=0$.",
   sol:[
    "$h'(x) = e^x$.",
    "$y = h(0)+h'(0)(x-0) = e^0 + e^0x$",
    "$y = 1+x$"],
   ans:"$y = 1+x$"},
  {id:"CN1.1.3-XR7", src:"Course notes 1.1, Exercise 7", lec:"L02", kind:"exercise", page:"p. 8",
   q:"Let $g(\\theta) = \\sin(\\theta)$. Find the equation of the tangent line to $y = g(\\theta)$ at $a = \\frac{\\pi}{6}$.",
   sol:[
    "$g'(\\theta) = \\cos(\\theta)$.",
    "$y = g\\!\\left(\\tfrac\\pi6\\right) + g'\\!\\left(\\tfrac\\pi6\\right)\\left(\\theta-\\tfrac\\pi6\\right) = \\sin\\!\\left(\\tfrac\\pi6\\right) + \\cos\\!\\left(\\tfrac\\pi6\\right)\\left(\\theta-\\tfrac\\pi6\\right)$",
    "$y = \\dfrac12 + \\dfrac{\\sqrt3}{2}\\left(\\theta - \\dfrac\\pi6\\right)$"],
   ans:"$y = \\frac12 + \\frac{\\sqrt3}{2}\\left(\\theta - \\frac\\pi6\\right)$"},
  {id:"CN1.1.3-EX12", src:"Course notes 1.1, Example 12", lec:"L02", kind:"example", page:"p. 9",
   q:"Find the equation of the tangent line to $f(x) = \\sqrt x$ at $a=9$. Use it to approximate $\\sqrt{10}$.",
   sol:[
    "$f'(x) = \\frac12 x^{-1/2}$, so the slope at $a=9$ is $f'(9) = \\frac12(9)^{-1/2} = \\frac12\\cdot\\frac13 = \\frac16$.",
    "Tangent line: $y = f(9) + f'(9)(x-9) = \\sqrt9 + \\tfrac16(x-9) = 3 + \\tfrac16(x-9)$",
    "By the tangent line approximation, $f(x) \\approx 3 + \\frac16(x-9)$ for $x$ near 9.",
    "Take $x=10$: $f(10) \\approx 3 + \\tfrac16(10-9)$, so $\\sqrt{10} \\approx \\tfrac{19}{6}$.",
    "(Check: $\\sqrt{10} = 3.162\\ldots$ and $\\frac{19}{6}\\approx 3.1667$.)"],
   ans:"$y = 3+\\frac16(x-9)$; $\\sqrt{10}\\approx \\frac{19}{6}$"},
  {id:"CN1.1.3-EX13", src:"Course notes 1.1, Example 13", lec:"L02", kind:"example", page:"pp. 9-10",
   q:"Find the equation of the tangent line to $f(x) = (1+x)^{1/3}$ at $a=0$. Use it to approximate $(1.1)^{1/3}$.",
   sol:[
    "$f'(x) = \\frac13(1+x)^{-2/3}$, so $f'(0) = \\frac13(1)^{-2/3} = \\frac13$.",
    "Tangent line: $y = f(0)+f'(0)(x-0) = 1 + \\tfrac13 x$",
    "So $f(x) \\approx 1 + \\frac13 x$ for $x$ near 0.",
    "Take $x = 0.1$ (not 1.1), because $f(0.1) = (1+0.1)^{1/3} = (1.1)^{1/3}$.",
    "$f(0.1) \\approx 1 + \\tfrac13(0.1)$, so $(1.1)^{1/3} \\approx 1 + \\tfrac1{30} = \\tfrac{31}{30}$"],
   ans:"$y = 1+\\frac13x$; $(1.1)^{1/3}\\approx\\frac{31}{30}$"},
  {id:"CN1.1.3-XR8", src:"Course notes 1.1, Exercise 8", lec:"L02", kind:"exercise", page:"p. 10",
   q:"Use the tangent line $y = 2 + \\frac14(x-4)$ of $f(x) = \\sqrt x$ at $a=4$ to approximate $\\sqrt2$. Explain why the tangent line gives a relatively poor approximation in this case.",
   sol:[
    "The tangent line approximates the function near $a=4$: $f(x) \\approx 2 + \\frac14(x-4)$.",
    "Take $x=2$: $\\sqrt2 \\approx 2 + \\tfrac14(2-4) = 1.5$",
    "Since $\\sqrt2 \\approx 1.41$, this is a relatively poor approximation, because $x=2$ is far from $a=4$."],
   ans:"$\\sqrt2\\approx 1.5$; poor because $x=2$ is far from $a=4$"},
  {id:"CN1.1.3-XR9", src:"Course notes 1.1, Exercise 9", lec:"L02", kind:"exercise", page:"p. 10",
   q:"Find the equation of the tangent line for $f(x) = \\cos(x)$ at $a=\\pi$ and use it to approximate $\\cos\\!\\left(\\frac{7\\pi}{8}\\right)$.",
   sol:[
    "$f'(x) = -\\sin(x)$.",
    "$y = f(\\pi)+f'(\\pi)(x-\\pi) = \\cos(\\pi) - \\sin(\\pi)(x-\\pi) = -1 + 0(x-\\pi)$, so $y = -1$",
    "So for $x$ near $\\pi$, $\\cos(x)\\approx -1$.",
    "Take $x = \\frac{7\\pi}{8}$: $\\cos\\!\\left(\\frac{7\\pi}8\\right) \\approx -1$"],
   ans:"$y=-1$; $\\cos\\left(\\frac{7\\pi}8\\right)\\approx -1$"},
  {id:"CN1.1.3-XR10", src:"Course notes 1.1, Exercise 10", lec:"L02", kind:"exercise", page:"p. 10",
   q:"Find the equation of the tangent line for $f(x) = \\sqrt[3]{x+2}$ at $a=6$ and use it to approximate $\\sqrt[3]9$.",
   sol:[
    "$f'(x) = \\frac13(x+2)^{-2/3}$.",
    "$y = f(6)+f'(6)(x-6) = \\sqrt[3]{8} + \\tfrac13(8)^{-2/3}(x-6) = 2+\\tfrac13\\cdot\\tfrac14(x-6) = 2+\\tfrac1{12}(x-6)$",
    "So $\\sqrt[3]{x+2} \\approx 2 + \\frac1{12}(x-6)$ for $x$ near 6.",
    "Take $x=7$: $\\sqrt[3]9 = f(7) \\approx 2 + \\tfrac1{12}(7-6) = \\tfrac{25}{12}$"],
   ans:"$y = 2+\\frac1{12}(x-6)$; $\\sqrt[3]9\\approx\\frac{25}{12}$"},
  {id:"CN1.1.3-XR11", src:"Course notes 1.1, Exercise 11", lec:"L02", kind:"exercise", page:"p. 10",
   q:"The position of an object is $s(t) = 17 + 3t + 2t^2$ m, where $t$ is in seconds. Find the equation of the tangent line for $s(t)$ at $t=1$ and use it to approximate $s(1.1)$.",
   sol:[
    "$s'(t) = 4t+3$.",
    "$y = s(1)+s'(1)(t-1) = (17+3(1)+2(1)^2) + (4(1)+3)(t-1) = 22 + 7(t-1)$",
    "So $s(t) \\approx 22 + 7(t-1)$ for $t$ near 1.",
    "$s(1.1) \\approx 22 + 7(1.1-1) = 22.7$",
    "After 1.1 s the object is at approximately 22.7 m."],
   ans:"$y = 22+7(t-1)$; $s(1.1)\\approx 22.7$ m"},
  {id:"CN1.1.4-EX14", src:"Course notes 1.1, Example 14", lec:"L02", kind:"example", page:"p. 12",
   q:"Approximate the change in the surface area of a spherical balloon when the radius decreases from 4 m to 3.9 m.",
   sol:[
    "The surface area is $S(r) = 4\\pi r^2$ m$^2$. The initial radius is $a=4$ m and $\\Delta r = 3.9 - 4 = -0.1$ m.",
    "$S'(r) = 8\\pi r$.",
    "By the differential approximation, $\\Delta S \\approx S'(4)\\,\\Delta r = (8\\pi\\cdot 4)(-0.1) = -3.2\\pi$ m$^2$"],
   ans:"$\\Delta S \\approx -3.2\\pi$ m$^2$"},
  {id:"CN1.1.4-EX15", src:"Course notes 1.1, Example 15", lec:"L02", kind:"example", page:"p. 12",
   q:"Let $f(x) = 2x^3 + 9x^2 - 24x + 6$. Approximate the change in $f(x)$ as $x$ changes from $x=1$ to $x=1.5$.",
   sol:[
    "$f'(x) = 6x^2+18x-24$. Here $a=1$ and $\\Delta x = 0.5$.",
    "$\\Delta y \\approx f'(1)\\Delta x = (6+18-24)(0.5) = 0$",
    "This does not make sense: the actual change is $\\Delta y = f(1.5)-f(1) = 4$.",
    "Part of the problem is that the tangent slope is 0 at $x=1$, so the approximation predicts no change. The main problem is that $\\Delta x = 0.5$ is too large. For a much smaller $\\Delta x$ the approximation would be fairly accurate."],
   ans:"The differential approximation gives $\\Delta y\\approx 0$, but the actual change is $4$ because $\\Delta x$ is too large."},
  {id:"CN1.1.4-XR12", src:"Course notes 1.1, Exercise 12", lec:"L02", kind:"exercise", page:"p. 12",
   q:"The rate of a reaction is $r(c) = kc^2 - 2kc + \\frac k2$, where $c$ is the concentration of the reactant and $k$ is a constant. Approximate the change in the reaction rate as $c$ changes from 2 to 2.1.",
   sol:[
    "$r'(c) = 2kc - 2k$. Initial value $c=2$, and $\\Delta c = 0.1$.",
    "$\\Delta r \\approx r'(2)\\Delta c = (4k-2k)(0.1) = 0.2k$"],
   ans:"$\\Delta r\\approx 0.2k$"},
  {id:"CN1.1.4-EX16", src:"Course notes 1.1, Example 16", lec:"L03", kind:"example", page:"p. 13",
   q:"Find $dy$ given $y = f(t) = t^2 + t - 2$. Determine the units of $dy$ given that $f$ is in meters and $t$ is in seconds.",
   sol:[
    "$dy = f'(t)\\,dt = (2t+1)\\,dt$",
    "Units: $f'(t)$ is in m/s and $dt$ is in s, so $dy$ is in $\\frac{\\text{m}}{\\text{s}}\\cdot\\text{s} = $ m.",
    "This makes sense: $dy$ is an infinitely small change in $f$, which is measured in meters."],
   ans:"$dy = (2t+1)\\,dt$, in meters"},
  {id:"CN1.1.4-EX17", src:"Course notes 1.1, Example 17", lec:"L03", kind:"example", page:"p. 14",
   q:"Find $du$ given $u = f(x) = \\cos(x^2)$.",
   sol:[
    "$du = f'(x)\\,dx$",
    "$du = \\left(-\\sin(x^2)\\cdot 2x\\right)dx = -2x\\sin(x^2)\\,dx$"],
   ans:"$du = -2x\\sin(x^2)\\,dx$"},
  {id:"CN1.1.4-XR13", src:"Course notes 1.1, Exercise 13", lec:"L03", kind:"exercise", page:"p. 14",
   q:"Find $dy$ given $y = f(t) = 5t^3 - 3t^2$. If $f(t)$ is in kilograms and $t$ is in minutes, what are the units of $dy$?",
   sol:[
    "$dy = f'(t)\\,dt = (15t^2-6t)\\,dt$",
    "The units of $f'(t)$ are kg/min and the units of $dt$ are min, so $dy$ is in kilograms."],
   ans:"$dy = (15t^2-6t)\\,dt$, in kg"},
  {id:"CN1.1.4-XR14", src:"Course notes 1.1, Exercise 14", lec:"L03", kind:"exercise", page:"p. 14",
   q:"Find $du$ given $u = f(x) = \\sin(x^2+x)$.",
   sol:[
    "$du = f'(x)\\,dx = (2x+1)\\cos(x^2+x)\\,dx$"],
   ans:"$du = (2x+1)\\cos(x^2+x)\\,dx$"},
  {id:"CN1.1.5-XR15", src:"Course notes 1.1, Exercise 15", lec:"L03", kind:"exercise", page:"p. 15",
   q:"State the order of the differential equation.<br>(a) $(y'')^3 + x^2y' = x$<br>(b) $\\left(\\dfrac{dy}{dx}\\right)^2 = y^4$<br>(c) $\\dfrac{d^3y}{dx^3} = \\dfrac{d^2y}{dx^2}$",
   sol:[
    "The order is the order of the highest derivative of $y$ in the equation.",
    "(a) The highest derivative is $y''$, so the DE is second-order.",
    "(b) The highest derivative is $\\frac{dy}{dx}$, so the DE is first-order.",
    "(c) The highest derivative is $\\frac{d^3y}{dx^3}$, so the DE is third-order."],
   ans:"(a) second-order; (b) first-order; (c) third-order"},
  {id:"CN1.1.5-EX18", src:"Course notes 1.1, Example 18", lec:"L03", kind:"example", page:"p. 16",
   q:"Show that $y(t) = 100e^{0.02t}$ is a solution of the differential equation $y' = 0.02y$.",
   sol:[
    "LHS: $y'(t) = 100e^{0.02t}\\cdot(0.02)$",
    "$= 0.02\\cdot 100e^{0.02t} = 0.02\\,y(t)$, which is the RHS.",
    "The LHS equals the RHS, so $y(t) = 100e^{0.02t}$ is a solution."],
   ans:"$y' = 0.02y$ holds, so it is a solution."},
  {id:"CN1.1.5-EX19", src:"Course notes 1.1, Example 19", lec:"L03", kind:"example", page:"p. 16",
   q:"Determine whether $y(x) = 3x^2+4$ is a solution of $y'' = x$.",
   sol:[
    "$y'(x) = 6x$ and $y''(x) = 6$.",
    "The LHS is $6$ and the RHS is $x$. These are not equal for all $x$, so $y = 3x^2+4$ is not a solution."],
   ans:"Not a solution"},
  {id:"CN1.1.5-XR16", src:"Course notes 1.1, Exercise 16", lec:"L03", kind:"exercise", page:"p. 16",
   q:"Which of the following is a solution of $\\dfrac{d^2f}{dx^2} = 1$?<br>(a) $f(x) = 3x^2+2x+1$<br>(b) $f(x) = e^x+\\cos(x)$<br>(c) $f(x) = \\frac12x^2+5x+3$<br>(d) $f(x) = \\frac12x^2 - \\sqrt2\\,x + 101$",
   sol:[
    "(a) $\\frac{df}{dx} = 6x+2$, $\\frac{d^2f}{dx^2} = 6$. LHS is 6, RHS is 1: not a solution.",
    "(b) $\\frac{df}{dx} = e^x - \\sin(x)$, $\\frac{d^2f}{dx^2} = e^x - \\cos(x)$, which is not identically 1: not a solution.",
    "(c) $\\frac{df}{dx} = x+5$, $\\frac{d^2f}{dx^2} = 1$. LHS = RHS: solution.",
    "(d) $\\frac{df}{dx} = x - \\sqrt2$, $\\frac{d^2f}{dx^2} = 1$. LHS = RHS: solution."],
   ans:"(c) and (d)"},
  {id:"CN1.1.5-EX20", src:"Course notes 1.1, Example 20", lec:"L03", kind:"example", page:"p. 17",
   q:"Show that $y(x) = \\frac13x^3 + C$ is a family of solutions of $y'(x) = x^2$.",
   sol:[
    "LHS: $y'(x) = \\frac13(3x^2) + 0 = x^2$, which is the RHS.",
    "So every function $y = \\frac13x^3+C$ is a solution: it is a family of solutions."],
   ans:"$y' = x^2$ for every $C$, so it is a family of solutions."},
  {id:"CN1.1.5-EX21", src:"Course notes 1.1, Example 21", lec:"L03", kind:"example", page:"p. 17",
   q:"Show that $y(x) = c_1e^{2x} + c_2$ is a family of solutions of $y'' = 2y'$.",
   sol:[
    "$y'(x) = 2c_1e^{2x}$ and $y''(x) = 4c_1e^{2x}$.",
    "LHS: $y'' = 4c_1e^{2x}$. RHS: $2y' = 2(2c_1e^{2x}) = 4c_1e^{2x}$.",
    "LHS = RHS, so every $y = c_1e^{2x}+c_2$ is a solution."],
   ans:"$y'' = 2y'$ for all $c_1, c_2$, so it is a family of solutions."},
  {id:"CN1.1.5-XR17", src:"Course notes 1.1, Exercise 17", lec:"L03", kind:"exercise", page:"p. 17",
   q:"Show that $y(x) = -\\cos(x) + C$ is a family of solutions of $y' = \\sin(x)$.",
   sol:[
    "LHS: $y'(x) = -(-\\sin(x)) + 0 = \\sin(x)$, which is the RHS.",
    "So $y = -\\cos(x)+C$ is a family of solutions."],
   ans:"$y' = \\sin(x)$ for every $C$"},
  {id:"CN1.1.5-XR18", src:"Course notes 1.1, Exercise 18", lec:"L03", kind:"exercise", page:"p. 17",
   q:"Show that $y(x) = \\frac12x^2 + C$ is a family of solutions of $y' = x$.",
   sol:[
    "LHS: $y'(x) = \\frac12(2x) + 0 = x$, which is the RHS.",
    "So $y = \\frac12x^2+C$ is a family of solutions."],
   ans:"$y' = x$ for every $C$"},
  {id:"CN1.1-P1-a-d", src:"Course notes 1.1, End of Section Problem 1, parts (a) to (d)", lec:"L01", kind:"problem", page:"p. 18",
   q:"Determine the derivative of each function.<br>(a) $f(x) = 5x^3-2x+1$<br>(b) $f(x) = \\sqrt{5x-2}$<br>(c) $f(x) = \\dfrac{1}{(3-x)^2}$<br>(d) $f(x) = e^x\\cos(x)$",
   sol:[
    "(a) $f'(x) = 5(3x^2) - 2 = 15x^2-2$",
    "(b) By the Chain Rule, $f'(x) = \\frac12(5x-2)^{-1/2}\\cdot 5 = \\dfrac{5}{2\\sqrt{5x-2}}$",
    "(c) Write $f(x) = (3-x)^{-2}$. By the Chain Rule, $f'(x) = -2(3-x)^{-3}\\cdot(-1) = \\dfrac{2}{(3-x)^3}$",
    "(d) By the Product Rule, $f'(x) = e^x\\cos(x) - e^x\\sin(x)$"],
   ans:"(a) $15x^2-2$; (b) $\\frac{5}{2\\sqrt{5x-2}}$; (c) $\\frac{2}{(3-x)^3}$; (d) $e^x\\cos(x) - e^x\\sin(x)$"},
  {id:"CN1.1-P1-e-h", src:"Course notes 1.1, End of Section Problem 1, parts (e) to (h)", lec:"L01", kind:"problem", page:"p. 18",
   q:"Determine the derivative of each function.<br>(e) $f(x) = \\dfrac{\\cos(x)}{\\sin(x)}$<br>(f) $f(x) = \\sqrt{1-x^2}$<br>(g) $f(x) = \\cos^3(x)$<br>(h) $f(x) = (x^3+x+1)^{2/3}$",
   sol:[
    "(e) By the Quotient Rule, $f'(x) = \\dfrac{-\\sin(x)\\sin(x) - \\cos(x)\\cos(x)}{\\sin^2(x)} = \\dfrac{-(\\sin^2(x)+\\cos^2(x))}{\\sin^2(x)} = \\dfrac{-1}{\\sin^2(x)}$",
    "(f) By the Chain Rule, $f'(x) = \\frac12(1-x^2)^{-1/2}\\cdot(-2x) = \\dfrac{-x}{\\sqrt{1-x^2}}$",
    "(g) By the Chain Rule, $f'(x) = 3\\cos^2(x)\\cdot(-\\sin(x)) = -3\\cos^2(x)\\sin(x)$",
    "(h) By the Chain Rule, $f'(x) = \\frac23(x^3+x+1)^{-1/3}\\cdot(3x^2+1) = \\dfrac{2(3x^2+1)}{3(x^3+x+1)^{1/3}}$"],
   ans:"(e) $\\frac{-1}{\\sin^2(x)}$; (f) $\\frac{-x}{\\sqrt{1-x^2}}$; (g) $-3\\cos^2(x)\\sin(x)$; (h) $\\frac{2(3x^2+1)}{3(x^3+x+1)^{1/3}}$"},
  {id:"CN1.1-P1-i-k", src:"Course notes 1.1, End of Section Problem 1, parts (i) to (k)", lec:"L01", kind:"problem", page:"p. 18",
   q:"Determine the derivative of each function.<br>(i) $f(x) = e^{\\sqrt{x^2+x}}$<br>(j) $f(x) = \\dfrac{1}{\\sqrt{x^2+1}}$<br>(k) $f(x) = \\dfrac{e^x-1}{e^x+1}$",
   sol:[
    "(i) By the Chain Rule (twice), $f'(x) = e^{\\sqrt{x^2+x}}\\cdot\\frac12(x^2+x)^{-1/2}\\cdot(2x+1) = e^{\\sqrt{x^2+x}}\\,\\dfrac{2x+1}{2\\sqrt{x^2+x}}$",
    "(j) Write $f(x) = (x^2+1)^{-1/2}$. By the Chain Rule, $f'(x) = -\\frac12(x^2+1)^{-3/2}\\cdot(2x) = \\dfrac{-x}{(x^2+1)^{3/2}}$",
    "(k) By the Quotient Rule, $f'(x) = \\dfrac{e^x(e^x+1) - (e^x-1)e^x}{(e^x+1)^2} = \\dfrac{2e^x}{(e^x+1)^2}$"],
   ans:"(i) $e^{\\sqrt{x^2+x}}\\frac{2x+1}{2\\sqrt{x^2+x}}$; (j) $\\frac{-x}{(x^2+1)^{3/2}}$; (k) $\\frac{2e^x}{(e^x+1)^2}$"},
  {id:"CN1.1-P2-a-d", src:"Course notes 1.1, End of Section Problem 2, parts (a) to (d)", lec:"L01", kind:"problem", page:"p. 18",
   q:"Determine the second derivative of each function.<br>(a) $f(x) = x^3-2x+3$<br>(b) $f(x) = x\\sqrt x$<br>(c) $f(x) = e^x$<br>(d) $f(x) = \\dfrac{\\sin(x)}{\\cos(x)}$",
   sol:[
    "(a) $f'(x) = 3x^2-2$",
    "$f''(x) = 6x$",
    "(b) Write $f(x) = x^{3/2}$. Then $f'(x) = \\frac32x^{1/2}$",
    "$f''(x) = \\frac34x^{-1/2}$",
    "(c) $f'(x) = e^x$",
    "$f''(x) = e^x$",
    "(d) By the Quotient Rule, $f'(x) = \\dfrac{\\cos(x)\\cos(x) - \\sin(x)(-\\sin(x))}{\\cos^2(x)} = \\dfrac{\\cos^2(x)+\\sin^2(x)}{\\cos^2(x)} = \\dfrac{1}{\\cos^2(x)}$",
    "Write $f'(x) = (\\cos(x))^{-2}$. By the Chain Rule, $f''(x) = -2(\\cos(x))^{-3}\\cdot(-\\sin(x)) = \\dfrac{2\\sin(x)}{\\cos^3(x)}$"],
   ans:"(a) $6x$; (b) $\\frac34x^{-1/2}$; (c) $e^x$; (d) $\\frac{2\\sin(x)}{\\cos^3(x)}$"},
  {id:"CN1.1-P2-e-h", src:"Course notes 1.1, End of Section Problem 2, parts (e) to (h)", lec:"L01", kind:"problem", page:"p. 18",
   q:"Determine the second derivative of each function.<br>(e) $f(x) = \\dfrac1{x^3}$<br>(f) $f(x) = \\dfrac1{\\sin(x)}$<br>(g) $f(x) = e^{-x^2}$<br>(h) $f(x) = \\cos(x)+x^2+2$",
   sol:[
    "(e) Write $f(x) = x^{-3}$. Then $f'(x) = -3x^{-4}$",
    "$f''(x) = 12x^{-5}$",
    "(f) Write $f(x) = (\\sin(x))^{-1}$. By the Chain Rule, $f'(x) = -(\\sin(x))^{-2}\\cos(x) = -\\dfrac{\\cos(x)}{\\sin^2(x)}$",
    "By the Quotient Rule, $f''(x) = -\\dfrac{-\\sin(x)\\sin^2(x) - \\cos(x)\\cdot 2\\sin(x)\\cos(x)}{\\sin^4(x)} = \\dfrac{\\sin^2(x)+2\\cos^2(x)}{\\sin^3(x)}$",
    "(g) By the Chain Rule, $f'(x) = e^{-x^2}\\cdot(-2x) = -2xe^{-x^2}$",
    "By the Product Rule, $f''(x) = -2e^{-x^2} + (-2x)e^{-x^2}(-2x) = -2e^{-x^2} + 4x^2e^{-x^2}$",
    "(h) $f'(x) = -\\sin(x)+2x$",
    "$f''(x) = -\\cos(x)+2$"],
   ans:"(e) $12x^{-5}$; (f) $\\frac{\\sin^2(x)+2\\cos^2(x)}{\\sin^3(x)}$; (g) $-2e^{-x^2}+4x^2e^{-x^2}$; (h) $-\\cos(x)+2$"},
  {id:"CN1.1-P2-i-k", src:"Course notes 1.1, End of Section Problem 2, parts (i) to (k)", lec:"L01", kind:"problem", page:"p. 18",
   q:"Determine the second derivative of each function.<br>(i) $f(x) = e^x\\sin(x)$<br>(j) $f(x) = (x-1)e^x$<br>(k) $f(x) = \\dfrac1x + \\sqrt x$",
   sol:[
    "(i) $f'(x) = e^x\\sin(x)+e^x\\cos(x)$",
    "$f''(x) = e^x\\sin(x)+e^x\\cos(x)+e^x\\cos(x)-e^x\\sin(x) = 2e^x\\cos(x)$",
    "(j) $f'(x) = e^x + (x-1)e^x = xe^x$",
    "$f''(x) = e^x + xe^x$",
    "(k) $f'(x) = -\\dfrac{1}{x^2} + \\dfrac{1}{2\\sqrt x}$",
    "$f''(x) = \\dfrac{2}{x^3} - \\dfrac{1}{4x^{3/2}}$"],
   ans:"(i) $2e^x\\cos(x)$; (j) $e^x+xe^x$; (k) $\\frac{2}{x^3}-\\frac{1}{4x^{3/2}}$"},
  {id:"CN1.1-P3", src:"Course notes 1.1, End of Section Problem 3", lec:"L02", kind:"problem", page:"p. 18",
   q:"Find the equation of the tangent line of the function at the given $a$.<br>(a) $f(x) = \\cos(x)$, $a=0$<br>(b) $f(x) = e^x$, $a=0$<br>(c) $f(x) = (1+x)^{1/5}$, $a=0$<br>(d) $f(x) = x^2+1$, $a=-1$<br>(e) $f(x) = x^3-x$, $a=1$<br>(f) $f(x) = \\dfrac{e^x}{x}$, $a=2$",
   sol:[
    "(a) $f'(x) = -\\sin(x)$",
    "$y = f(0)+f'(0)(x-0) = 1 + 0(x-0) = 1$",
    "(b) $f'(x) = e^x$",
    "$y = f(0)+f'(0)(x-0) = 1 + 1(x-0) = 1+x$",
    "(c) $f'(x) = \\frac15(1+x)^{-4/5}$",
    "$y = f(0)+f'(0)(x-0) = 1+\\tfrac15(x-0) = 1+\\tfrac15x$",
    "(d) $f'(x) = 2x$",
    "$y = f(-1)+f'(-1)(x-(-1)) = 2 + (-2)(x+1) = 2-2(x+1)$",
    "(e) $f'(x) = 3x^2-1$",
    "$y = f(1)+f'(1)(x-1) = 0 + 2(x-1) = 2(x-1)$",
    "(f) By the Quotient Rule, $f'(x) = \\dfrac{xe^x-e^x}{x^2}$, so $f'(2) = \\dfrac{2e^2-e^2}{2^2} = \\dfrac{e^2}{4}$",
    "$y = f(2)+f'(2)(x-2) = \\dfrac{e^2}{2} + \\dfrac{e^2}{4}(x-2)$"],
   ans:"(a) $y=1$; (b) $y=1+x$; (c) $y=1+\\frac15x$; (d) $y=2-2(x+1)$; (e) $y=2(x-1)$; (f) $y=\\frac{e^2}{2}+\\frac{e^2}{4}(x-2)$"},
  {id:"CN1.1-P4", src:"Course notes 1.1, End of Section Problem 4", lec:"L02", kind:"problem", page:"p. 18",
   q:"Use the tangent line of $f$ at $a$ to approximate the given value.<br>(a) $f(x) = \\sqrt x$, $a=9$; approximate $\\sqrt{10}$<br>(b) $f(x) = x^{2/3}$, $a=8$; approximate $7^{2/3}$<br>(c) $f(x) = \\sin(x)$, $a=0$; approximate $\\sin(0.1)$<br>(d) $f(x) = (1+x)^{1/4}$, $a=0$; approximate $(1.001)^{1/4}$<br>(e) $f(x) = (1+x)^{1/3}$, $a=0$; approximate $(0.99)^{1/3}$",
   sol:[
    "(a) $f'(x) = \\frac12x^{-1/2}$. Tangent line: $y = f(9)+f'(9)(x-9) = 3+\\frac16(x-9)$",
    "So $f(x)\\approx 3+\\frac16(x-9)$. Take $x=10$: $\\sqrt{10} = f(10) \\approx 3+\\frac16(10-9) = \\frac{19}6$",
    "(b) $f'(x) = \\frac23x^{-1/3}$. Tangent line: $y = f(8)+f'(8)(x-8) = 4+\\frac13(x-8)$",
    "Take $x=7$: $7^{2/3} = f(7)\\approx 4+\\frac13(7-8) = \\frac{11}3$",
    "(c) $f'(x) = \\cos(x)$. Tangent line: $y = f(0)+f'(0)(x-0) = 0+1(x-0) = x$",
    "Take $x = 0.1$: $\\sin(0.1) = f(0.1)\\approx 0.1$",
    "(d) $f'(x) = \\frac14(1+x)^{-3/4}$. Tangent line: $y = 1+\\frac14(x-0) = 1+\\frac14x$",
    "Take $x = 0.001$: $(1.001)^{1/4} = f(0.001)\\approx 1+\\frac14\\cdot\\frac1{1000} = \\frac{4001}{4000}$",
    "(e) $f'(x) = \\frac13(1+x)^{-2/3}$. Tangent line: $y = 1+\\frac13(x-0) = 1+\\frac13x$",
    "Take $x=-0.01$: $(0.99)^{1/3} = f(-0.01) \\approx 1+\\frac13\\left(-\\frac1{100}\\right) = \\frac{299}{300}$"],
   ans:"(a) $\\frac{19}{6}$; (b) $\\frac{11}{3}$; (c) $0.1$; (d) $\\frac{4001}{4000}$; (e) $\\frac{299}{300}$"},
  {id:"CN1.1-P5", src:"Course notes 1.1, End of Section Problem 5", lec:"L03", kind:"problem", page:"p. 18",
   q:"Find the differential $du$.<br>(a) $u = x^2+x$<br>(b) $u = \\cos(3x+1)$<br>(c) $u = \\sqrt{2x+3}$<br>(d) $u = e^{x^2}$<br>(e) $u = x^2e^x$",
   sol:[
    "(a) $du = u'(x)\\,dx = (2x+1)\\,dx$",
    "(b) $du = u'(x)\\,dx = -\\sin(3x+1)\\cdot 3\\,dx = -3\\sin(3x+1)\\,dx$",
    "(c) $du = u'(x)\\,dx = \\frac12(2x+3)^{-1/2}\\cdot 2\\,dx = \\dfrac{1}{\\sqrt{2x+3}}\\,dx$",
    "(d) $du = u'(x)\\,dx = e^{x^2}\\cdot 2x\\,dx = 2xe^{x^2}\\,dx$",
    "(e) By the Product Rule, $du = u'(x)\\,dx = (2xe^x + x^2e^x)\\,dx$"],
   ans:"(a) $du=(2x+1)\\,dx$; (b) $du=-3\\sin(3x+1)\\,dx$; (c) $du=\\frac{1}{\\sqrt{2x+3}}\\,dx$; (d) $du=2xe^{x^2}\\,dx$; (e) $du=(2xe^x+x^2e^x)\\,dx$"},
  {id:"CN1.1-P6", src:"Course notes 1.1, End of Section Problem 6", lec:"L02", kind:"problem", page:"p. 18",
   q:"Use the differential approximation to approximate the change in $y$.<br>(a) $y = \\sqrt x$ as $x$ changes from $x=9$ to $x=10$<br>(b) $y = x^{2/3}$ as $x$ changes from $x=8$ to $x=7$<br>(c) $y = x^2+3x-1$ as $x$ changes from $x=1$ to $x=1.1$<br>(d) $y = \\dfrac1x$ as $x$ changes from $x=2$ to $x=1.9$<br>(e) $y = \\dfrac2{x^2}$ as $x$ changes from $x=2$ to $x=2.2$<br>(f) $y = \\sin(x)$ as $x$ changes from $x=\\frac\\pi4$ to $x=\\frac\\pi5$",
   sol:[
    "(a) $f'(x) = \\dfrac{1}{2\\sqrt x}$, $a=9$, $\\Delta x = 1$.",
    "$\\Delta y \\approx f'(9)\\Delta x = \\dfrac{1}{2\\sqrt9}\\cdot1 = \\dfrac16$",
    "(b) $f'(x) = \\frac23x^{-1/3}$, $a=8$, $\\Delta x = -1$.",
    "$\\Delta y\\approx f'(8)\\Delta x = \\frac23(8)^{-1/3}\\cdot(-1) = -\\frac13$",
    "(c) $f'(x) = 2x+3$, $a=1$, $\\Delta x = 0.1$.",
    "$\\Delta y\\approx f'(1)\\Delta x = (2(1)+3)(0.1) = 0.5$",
    "(d) $f'(x) = -x^{-2}$, $a=2$, $\\Delta x = -0.1$.",
    "$\\Delta y\\approx f'(2)\\Delta x = -\\frac1{2^2}\\cdot(-0.1) = \\frac1{40}$",
    "(e) $f'(x) = -4x^{-3}$, $a=2$, $\\Delta x = 0.2$.",
    "$\\Delta y\\approx f'(2)\\Delta x = -\\frac4{2^3}\\cdot(0.2) = -\\frac1{10}$",
    "(f) $f'(x) = \\cos(x)$, $a = \\frac\\pi4$, $\\Delta x = \\frac\\pi5-\\frac\\pi4 = -\\frac\\pi{20}$.",
    "$\\Delta y\\approx f'\\!\\left(\\frac\\pi4\\right)\\Delta x = \\frac1{\\sqrt2}\\left(-\\frac\\pi{20}\\right) = -\\frac{\\pi}{20\\sqrt2}$"],
   ans:"(a) $\\frac16$; (b) $-\\frac13$; (c) $0.5$; (d) $\\frac1{40}$; (e) $-\\frac1{10}$; (f) $-\\frac{\\pi}{20\\sqrt2}$",
   note:"Compare (a) with Problem 4(a) and (b) with Problem 4(b)."},
  {id:"CN1.1-P7", src:"Course notes 1.1, End of Section Problem 7", lec:"L02", kind:"problem", page:"p. 18",
   q:"The surface area $S$ of a spherical cell is related to its volume $V$ by $S = (36\\pi V^2)^{1/3}$. Approximate the change in surface area when the volume increases from 10 $\\mu$m$^3$ to 10.5 $\\mu$m$^3$.",
   sol:[
    "$S(V) = (36\\pi)^{1/3}V^{2/3}$, with $a = 10$ and $\\Delta V = 0.5$.",
    "$S'(V) = (36\\pi)^{1/3}\\cdot\\frac23V^{-1/3}$",
    "$\\Delta S \\approx S'(10)\\Delta V = (36\\pi)^{1/3}\\cdot\\tfrac23(10)^{-1/3}\\cdot\\tfrac12 = \\tfrac13\\left(\\tfrac{36\\pi}{10}\\right)^{1/3} = \\tfrac13(3.6\\pi)^{1/3}$",
    "The surface area increases by approximately $\\frac13(3.6\\pi)^{1/3}$ $\\mu$m$^2$."],
   ans:"$\\Delta S\\approx\\frac13(3.6\\pi)^{1/3}$ $\\mu$m$^2$ (about $0.75$ $\\mu$m$^2$)"},
  {id:"CN1.1-P8", src:"Course notes 1.1, End of Section Problem 8", lec:"L02", kind:"problem", page:"p. 18",
   q:"Suppose the size of a bacterial population satisfies $\\dfrac{dN}{dt} = 0.02N$, where $t$ is in days and $N$ is in millions. If $N(10) = 250$, approximate the change in the population when time changes from 10 days to 10.5 days.",
   sol:[
    "Initial time $t=10$ and $\\Delta t = 0.5$. By the differential approximation, $\\Delta N\\approx N'(10)\\Delta t$.",
    "From the DE, $N'(10) = 0.02N(10) = 0.02(250) = 5$.",
    "$\\Delta N\\approx 5(0.5) = 2.5$",
    "The population increases by approximately 2.5 million between day 10 and day 10.5."],
   ans:"$\\Delta N\\approx 2.5$ million"},
  {id:"CN1.1-P9", src:"Course notes 1.1, End of Section Problem 9", lec:"L01", kind:"problem", page:"p. 19",
   q:"The population in millions of arctic flounder is $P(t) = \\dfrac{8t+1}{t^2+1}$, where $t$ is the number of years since the beginning of 1980.<br>(a) Calculate $P'(t)$ and state its units.<br>(b) Find $P'(1)$ and briefly interpret its meaning.<br>(c) Calculate $P(1)$ and $P(2)$. Explain why the difference between $P(1)$ and $P(2)$ does not contradict your answer in (b).",
   sol:[
    "(a) By the Quotient Rule, $P'(t) = \\dfrac{8(t^2+1) - (8t+1)(2t)}{(t^2+1)^2} = \\dfrac{-8t^2-2t+8}{(t^2+1)^2}$",
    "The units are millions of fish per year.",
    "(b) $P'(1) = \\dfrac{-8-2+8}{(1^2+1)^2} = -\\dfrac12$ million per year.",
    "At the beginning of 1981 the population is decreasing at a rate of $\\frac12$ million fish per year.",
    "(c) $P(1) = \\dfrac{8+1}{1^2+1} = \\dfrac92$ million and $P(2) = \\dfrac{16+1}{2^2+1} = \\dfrac{17}5$ million.",
    "The change over the year is $P(2)-P(1) = 3.4 - 4.5 = -1.1$ million.",
    "This does not contradict $P'(1) = -\\frac12$ million/year, because $P'(1)$ is the instantaneous rate at the beginning of 1981, and the rate is not constant over the year."],
   ans:"(a) $P'(t) = \\frac{-8t^2-2t+8}{(t^2+1)^2}$ million fish/year; (b) $P'(1) = -\\frac12$ million/year; (c) $P(1)=\\frac92$, $P(2)=\\frac{17}{5}$ million"},
  {id:"CN1.1-P10", src:"Course notes 1.1, End of Section Problem 10", lec:"L02", kind:"problem", page:"p. 19",
   q:"The head circumference of a fetus is $H(t) = -30 + 1.5t^2$ mm, where $t$ is in weeks. Approximate the change in head circumference between $t=8$ and $t=9$ weeks.",
   sol:[
    "$H'(t) = 3t$, with $a=8$ and $\\Delta t = 1$.",
    "$\\Delta H\\approx H'(8)\\Delta t = 3(8)(1) = 24$",
    "The head circumference increases by approximately 24 mm."],
   ans:"$\\Delta H\\approx 24$ mm"},
  {id:"CN1.1-P11", src:"Course notes 1.1, End of Section Problem 11", lec:"L01", kind:"problem", page:"p. 19",
   q:"Assume that $m(t)$ is the mass of an object in kg at time $t$ in hours.<br>(a) What are the units of $m'(t)$ and $m''(t)$?<br>(b) What does $m'(2) = 2$ mean physically?",
   sol:[
    "(a) $m'(t)$ is in kg/h and $m''(t)$ is in kg/h$^2$.",
    "(b) At $t = 2$ hours the object is gaining mass at a rate of 2 kg/h."],
   ans:"(a) kg/h and kg/h$^2$; (b) at $t=2$ h the mass is increasing at 2 kg/h"},
  {id:"CN1.1-P12", src:"Course notes 1.1, End of Section Problem 12", lec:"L01", kind:"problem", page:"p. 19",
   q:"For a certain dosage of a drug, $d$ (in mg), the temperature change (in °F) is $T(d) = 0.05d - 0.3d^2$. Find the rate of change of the temperature with respect to the dosage and indicate the units.",
   sol:[
    "$T'(d) = 0.05 - 0.6d$",
    "$T$ is in °F and $d$ is in mg, so $T'(d)$ is in degrees Fahrenheit per mg."],
   ans:"$T'(d) = 0.05-0.6d$ °F/mg"},
  {id:"CN1.1-P13-a-d", src:"Course notes 1.1, End of Section Problem 13, parts (a) to (d)", lec:"L03", kind:"problem", page:"p. 19",
   q:"State the order of the differential equation.<br>(a) $y' = 2y(x-y)$<br>(b) $y'' + 10y' - 5 = 2x+3$<br>(c) $\\dfrac{dy}{dx} = y + x$<br>(d) $x^2\\dfrac{dy}{dx} = xy^3+1$",
   sol:[
    "(a) The highest derivative of $y$ is $y'$, so the DE is first-order.",
    "(b) The highest derivative of $y$ is $y''$, so the DE is second-order.",
    "(c) The highest derivative of $y$ is $\\frac{dy}{dx}$, so the DE is first-order.",
    "(d) The highest derivative of $y$ is $\\frac{dy}{dx}$, so the DE is first-order."],
   ans:"(a) first-order; (b) second-order; (c) first-order; (d) first-order"},
  {id:"CN1.1-P13-e-g", src:"Course notes 1.1, End of Section Problem 13, parts (e) to (g)", lec:"L03", kind:"problem", page:"p. 19",
   q:"State the order of the differential equation.<br>(e) $y''+y'+y = 0$<br>(f) $\\left(\\dfrac{d^3y}{dx^3}\\right)^2 = y$<br>(g) $xy' = y$",
   sol:[
    "(e) The highest derivative of $y$ is $y''$, so the DE is second-order.",
    "(f) The highest derivative of $y$ is $\\frac{d^3y}{dx^3}$, so the DE is third-order.",
    "(g) The highest derivative of $y$ is $y'$, so the DE is first-order."],
   ans:"(e) second-order; (f) third-order; (g) first-order"},
  {id:"CN1.1-P14-a-d", src:"Course notes 1.1, End of Section Problem 14, parts (a) to (d)", lec:"L03", kind:"problem", page:"p. 19",
   q:"Determine whether the given function is a family of solutions of the differential equation.<br>(a) $y = x+C$ for $y' = x+2$<br>(b) $y = Cx^2$ for $\\dfrac{dy}{dx} = y^2$<br>(c) $y = Ce^x$ for $\\dfrac{dy}{dx} = y$<br>(d) $y = Cx$ for $y' = \\dfrac yx$",
   sol:[
    "(a) LHS: $y' = 1$. RHS: $x+2$. These are not equal for all $x$, so $y = x+C$ is not a family of solutions.",
    "(b) LHS: $y' = 2Cx$. RHS: $y^2 = (Cx^2)^2 = C^2x^4$.",
    "These are not equal for arbitrary $C$, so this is not a family of solutions.",
    "(c) LHS: $y' = Ce^x$. RHS: $y = Ce^x$.",
    "LHS = RHS, so it is a family of solutions.",
    "(d) LHS: $y' = C$. RHS: $\\dfrac yx = \\dfrac{Cx}x = C$.",
    "LHS = RHS, so it is a family of solutions."],
   ans:"(a) not a solution; (b) not a solution; (c) solution; (d) solution"},
  {id:"CN1.1-P14-e-h", src:"Course notes 1.1, End of Section Problem 14, parts (e) to (h)", lec:"L03", kind:"problem", page:"p. 19",
   q:"Determine whether the given function is a family of solutions of the differential equation.<br>(e) $y = -\\dfrac{1}{e^x+C}$ for $y' = e^xy^2$<br>(f) $y = -3x+Cx^2$ for $\\dfrac{dy}{dx} - \\dfrac2xy = 3$<br>(g) $y = a\\cos(t)+b\\sin(t)$ for $\\dfrac{d^2y}{dt^2}+y = 0$<br>(h) $y = Ce^{3x}+1$ for $y''-y'-6y = 0$",
   sol:[
    "(e) Write $y = -(e^x+C)^{-1}$. LHS: $y' = (e^x+C)^{-2}e^x = \\dfrac{e^x}{(e^x+C)^2}$.",
    "RHS: $e^xy^2 = e^x\\left(-\\dfrac1{e^x+C}\\right)^2 = \\dfrac{e^x}{(e^x+C)^2}$.",
    "LHS = RHS, so it is a family of solutions.",
    "(f) $y' = -3+2Cx$.",
    "LHS: $y' - \\dfrac2xy = -3+2Cx - \\dfrac2x(-3x+Cx^2) = -3+2Cx+6-2Cx = 3$. RHS: 3.",
    "LHS = RHS, so it is a family of solutions.",
    "(g) $y' = -a\\sin(t)+b\\cos(t)$ and $y'' = -a\\cos(t)-b\\sin(t)$.",
    "LHS: $y''+y = [-a\\cos(t)-b\\sin(t)] + [a\\cos(t)+b\\sin(t)] = 0$, which is the RHS.",
    "So it is a family of solutions.",
    "(h) $y' = 3Ce^{3x}$ and $y'' = 9Ce^{3x}$.",
    "LHS: $9Ce^{3x}-3Ce^{3x}-6(Ce^{3x}+1) = -6$. RHS: 0.",
    "$-6\\neq 0$, so it is not a family of solutions."],
   ans:"(e) solution; (f) solution; (g) solution; (h) not a solution"},
  {id:"CN1.2.1-WK1", src:"Course notes 1.2.1, worked derivation", lec:"L04", kind:"example", page:"pp. 20-22",
   q:"An object moves with velocity $s'(t) = v(t) = t^2$ m/s. Use the left Riemann sum to approximate the distance it travels from $t=1$ s to $t=2$ s, first with $n=4$ subintervals and then with $n=8$.",
   sol:[
    "$n=4$: $\\Delta t = \\frac{2-1}{4} = \\frac14$ s, so the subintervals are $\\left[1,\\frac54\\right],\\left[\\frac54,\\frac64\\right],\\left[\\frac64,\\frac74\\right],\\left[\\frac74,2\\right]$.",
    "On each subinterval, $\\Delta s_i \\approx v(t_i)\\Delta t$ with $t_i$ the left endpoint:",
    "$\\Delta s_1 \\approx (1)^2\\cdot\\frac14 = \\frac14$, $\\Delta s_2\\approx\\left(\\frac54\\right)^2\\cdot\\frac14 = \\frac{25}{64}$, $\\Delta s_3\\approx\\left(\\frac32\\right)^2\\cdot\\frac14 = \\frac9{16}$, $\\Delta s_4\\approx\\left(\\frac74\\right)^2\\cdot\\frac14 = \\frac{49}{64}$",
    "$\\Delta s \\approx \\frac14 + \\frac{25}{64} + \\frac9{16} + \\frac{49}{64} = \\frac{63}{32}$ m",
    "$n=8$: $\\Delta t = \\frac{2-1}8 = \\frac18$ and $t_i = 1 + \\frac i8$ for $0\\le i\\le 7$, so the last subinterval is $[t_7,t_8] = \\left[\\frac{15}8,2\\right]$.",
    "$\\Delta s\\approx \\sum_{i=0}^{7} v(t_i)\\Delta t = \\tfrac18\\left[1^2 + \\left(\\tfrac98\\right)^2 + \\left(\\tfrac{10}8\\right)^2 + \\left(\\tfrac{11}8\\right)^2 + \\left(\\tfrac{12}8\\right)^2 + \\left(\\tfrac{13}8\\right)^2 + \\left(\\tfrac{14}8\\right)^2 + \\left(\\tfrac{15}8\\right)^2\\right] = \\tfrac{275}{128}$ m",
    "(The exact value, found later in Example 10, is $\\frac73$ m.)"],
   ans:"$n=4$: $\\frac{63}{32}$ m; $n=8$: $\\frac{275}{128}$ m",
   note:"The notes give the velocity in m/s$^2$; velocity is in m/s. The notes also print the last $n=8$ subinterval as $\\left[\\frac{17}{8},2\\right]$; it should be $\\left[\\frac{15}{8},2\\right]$."},
  {id:"CN1.2.1-EX1", src:"Course notes 1.2, Example 1", lec:"L04", kind:"example", page:"p. 23",
   q:"The rate of change of a quantity $F(t)$ is $f(t) = \\sin(t)$ for $0\\le t\\le\\pi$. Use the left Riemann sum with $n=4$ to approximate the net change in $F$ from $t=0$ to $t=\\pi$.",
   sol:[
    "$\\Delta t = \\dfrac{b-a}n = \\dfrac{\\pi-0}4 = \\dfrac\\pi4$ and $t_i = a+i\\Delta t = i\\cdot\\dfrac\\pi4$.",
    "Endpoints: $t_0 = 0$, $t_1 = \\frac\\pi4$, $t_2 = \\frac\\pi2$, $t_3 = \\frac{3\\pi}4$, $t_4 = \\pi$.",
    "$\\Delta F\\approx f(t_0)\\Delta t + f(t_1)\\Delta t + f(t_2)\\Delta t + f(t_3)\\Delta t = f(0)\\Delta t + f\\!\\left(\\tfrac\\pi4\\right)\\Delta t + f\\!\\left(\\tfrac\\pi2\\right)\\Delta t + f\\!\\left(\\tfrac{3\\pi}4\\right)\\Delta t$",
    "$= 0\\cdot\\tfrac\\pi4 + \\tfrac1{\\sqrt2}\\cdot\\tfrac\\pi4 + 1\\cdot\\tfrac\\pi4 + \\tfrac1{\\sqrt2}\\cdot\\tfrac\\pi4 = \\left(1+\\sqrt2\\right)\\tfrac\\pi4$"],
   ans:"$\\Delta F\\approx(1+\\sqrt2)\\frac\\pi4$",
   note:"The first line of the sum in the notes lists only three terms; the sum has four terms, as written here. The final answer in the notes is correct."},
  {id:"CN1.2.1-EX2", src:"Course notes 1.2, Example 2", lec:"L04", kind:"example", page:"p. 24",
   q:"The rate of change of a quantity $F(t)$ is $f(t) = \\dfrac1{t^2+t}$ for $1\\le t\\le4$. Use the left Riemann sum with $n=3$ to approximate the net change in $F$ from $t=1$ to $t=4$.",
   sol:[
    "$\\Delta t = \\dfrac{b-a}n = \\dfrac{4-1}3 = 1$ and $t_i = a+i\\Delta t = 1+i$.",
    "Endpoints: $t_0 = 1$, $t_1 = 2$, $t_2 = 3$, $t_3 = 4$.",
    "$\\Delta F\\approx f(1)\\Delta t + f(2)\\Delta t + f(3)\\Delta t = \\tfrac12(1) + \\tfrac16(1) + \\tfrac1{12}(1) = \\tfrac34$"],
   ans:"$\\Delta F\\approx\\frac34$"},
  {id:"CN1.2.1-XR1", src:"Course notes 1.2, Exercise 1", lec:"L04", kind:"exercise", page:"p. 24",
   q:"The rate of change of a quantity $F(t)$ is $f(t) = \\dfrac1t$ for $1\\le t\\le2$. Use the left Riemann sum with $n=3$ to approximate the net change in $F$ from $t=1$ to $t=2$.",
   sol:[
    "$\\Delta t = \\dfrac{2-1}3 = \\dfrac13$ and $t_i = 1+\\dfrac i3$, so $t_0 = 1$, $t_1 = \\frac43$, $t_2 = \\frac53$.",
    "$\\Delta F\\approx \\dfrac1{t_0}\\Delta t + \\dfrac1{t_1}\\Delta t + \\dfrac1{t_2}\\Delta t = 1\\cdot\\dfrac13 + \\dfrac34\\cdot\\dfrac13 + \\dfrac35\\cdot\\dfrac13$",
    "$= \\dfrac13+\\dfrac14+\\dfrac15 = \\dfrac{20}{60}+\\dfrac{15}{60}+\\dfrac{12}{60} = \\dfrac{47}{60}$"],
   ans:"$\\Delta F\\approx\\frac{47}{60}$"},
  {id:"CN1.2.1-XR2", src:"Course notes 1.2, Exercise 2", lec:"L04", kind:"exercise", page:"p. 24",
   q:"A function $g$ is given by a graph on $0\\le t\\le 4$: a smooth curve that decreases from about 3, with $g(1)=3$, $g(2)=2$ and $g(3)=1$, and rises slightly near $t=4$. Let $f(x) = \\displaystyle\\int_1^x g(t)\\,dt$. Use the left Riemann sum with $n=3$ to approximate $f(4)$.",
   sol:[
    "$f(4) = \\int_1^4 g(t)\\,dt$ is the net change from $t=1$ to $t=4$.",
    "$\\Delta t = \\dfrac{4-1}3 = 1$ and $t_i = 1+i$, so $t_0=1$, $t_1=2$, $t_2=3$.",
    "$f(4)\\approx g(1)\\Delta t + g(2)\\Delta t + g(3)\\Delta t = 3(1) + 2(1) + 1(1) = 6$"],
   ans:"$f(4)\\approx 6$",
   note:"The values of $g$ come from a graph in the notes; the official solution uses $g(1)=3$, $g(2)=2$, $g(3)=1$, which are stated here."},
  {id:"CN1.2.1-EX3", src:"Course notes 1.2, Example 3", lec:"L04", kind:"example", page:"p. 26",
   q:"Write each shaded area as a definite integral.<br>(a) The region under the graph of $f(x) = \\sin(x)+2$ from $x = \\frac\\pi2$ to $x = \\frac{3\\pi}2$ is shaded.<br>(b) The region between the graph of $f(t) = t^3-3t$ and the $t$-axis from $t=1$ to $t=2$ is shaded (the graph is below the axis at $t=1$ and above it at $t=2$).",
   sol:[
    "(a) The area under $f(x) = \\sin(x)+2$ from $x=\\frac\\pi2$ to $x=\\frac{3\\pi}2$ is $\\displaystyle\\int_{\\pi/2}^{3\\pi/2}(\\sin(x)+2)\\,dx$",
    "(b) The (signed) area under $f(t) = t^3-3t$ from $t=1$ to $t=2$ is $\\displaystyle\\int_1^2(t^3-3t)\\,dt$"],
   ans:"(a) $\\int_{\\pi/2}^{3\\pi/2}(\\sin(x)+2)\\,dx$; (b) $\\int_1^2(t^3-3t)\\,dt$"},
  {id:"CN1.2.1-EX4", src:"Course notes 1.2, Example 4", lec:"L04", kind:"example", page:"p. 26",
   q:"If $v(t) = 70(1+\\sin(2\\pi t))$ mL/s is the rate at which blood flows out of the heart, what does $\\displaystyle\\int_0^5 v(t)\\,dt$ represent?",
   sol:[
    "The integral of a rate is the net change of the quantity. So $\\int_0^5 v(t)\\,dt$ is the amount of blood (in mL) that the heart pumps out in the first 5 seconds."],
   ans:"The amount of blood (mL) pumped out of the heart in 5 seconds"},
  {id:"CN1.2.1-EX5", src:"Course notes 1.2, Example 5", lec:"L04", kind:"example", page:"p. 26",
   q:"If $b(t)$ is the yearly birth rate and $d(t)$ is the yearly death rate of a population, what does $\\displaystyle\\int_0^2(b(t)-d(t))\\,dt$ represent?",
   sol:[
    "$b(t)-d(t)$ is the rate of change of the population, so the integral is the net change in the population over the 2 year period."],
   ans:"The net change in the population over 2 years"},
  {id:"CN1.2.1-EX6", src:"Course notes 1.2, Example 6", lec:"L04", kind:"example", page:"p. 27",
   q:"An object accelerates at $a(t) = t$ m/s$^2$ from $t=0$ s to $t=3$ s. What is the change in velocity?",
   sol:[
    "The net change in velocity is the area under the acceleration graph from $t=0$ to $t=3$.",
    "The graph of $a(t) = t$ on $0\\le t\\le3$ forms a triangle with base 3 and height 3.",
    "$\\Delta v = \\frac12(3)(3) = \\frac92$ m/s"],
   ans:"$\\Delta v = \\frac92$ m/s"},
  {id:"CN1.2.1-XR3", src:"Course notes 1.2, Exercise 3", lec:"L04", kind:"exercise", page:"p. 27",
   q:"An object accelerates at $a(t) = -t+1$ m/s$^2$ from $t=0$ s to $t=3$ s. What is the net change in velocity?",
   sol:[
    "The net change in velocity is the signed area under the acceleration graph. Split the region into two triangles.",
    "From $t=0$ to $t=1$ the graph is above the axis: area $\\frac12(1)(1) = \\frac12$.",
    "From $t=1$ to $t=3$ the graph is below the axis (it reaches $a(3) = -2$): signed area $\\frac12(2)(-2) = -2$.",
    "Net change in velocity $= \\frac12 - 2 = -\\frac32$ m/s"],
   ans:"$\\Delta v = -\\frac32$ m/s"},
  {id:"CN1.2.1-XR4", src:"Course notes 1.2, Exercise 4", lec:"L04", kind:"exercise", page:"p. 27",
   q:"The rate of change of an animal's weight from $t=0$ to $t=\\sqrt2$ years is $w'(t) = \\sqrt{2-t^2}$. Given that the graph of $w'(t)$ for $0\\le t\\le\\sqrt2$ is one quarter of a circle of radius $\\sqrt2$, find the net change in the animal's weight.",
   sol:[
    "The net change is the area under the graph of $w'(t)$, which is a quarter circle of radius $\\sqrt2$:",
    "$\\Delta w = \\dfrac{\\pi r^2}4 = \\dfrac{\\pi(\\sqrt2)^2}4 = \\dfrac{2\\pi}4 = \\dfrac\\pi2$"],
   ans:"$\\Delta w = \\frac\\pi2$"},
  {id:"CN1.2.1-EX7", src:"Course notes 1.2, Example 7", lec:"L04", kind:"example", page:"p. 27",
   q:"What is the area under the graph of $F'(x) = 3x^2$ from $x=0$ to $x=2$?",
   sol:[
    "We need a function $F$ with this rate of change: $F(x) = x^3$ gives $F'(x) = 3x^2$.",
    "The net change from $x=0$ to $x=2$ is $\\Delta F = \\int_0^2F'(x)\\,dx = F(2)-F(0) = 2^3-0^3 = 8$",
    "Since area equals net change, the area under $y = 3x^2$ from 0 to 2 is 8."],
   ans:"$8$"},
  {id:"CN1.2.1-XR5", src:"Course notes 1.2, Exercise 5", lec:"L04", kind:"exercise", page:"p. 27",
   q:"In Example 7, $F(x) = x^3+1$ also satisfies $F'(x) = 3x^2$. What would be the net change from $x=0$ to $x=2$ using this $F$?",
   sol:[
    "$\\Delta F = \\int_0^2F'(x)\\,dx = F(2)-F(0) = [2^3+1]-[0^3+1] = 8$",
    "It is still 8: the area under the graph does not change, and the constants $+1$ cancel."],
   ans:"$8$"},
  {id:"CN1.2.1-EX8", src:"Course notes 1.2, Example 8", lec:"L04", kind:"example", page:"p. 28",
   q:"Evaluate $\\displaystyle\\int_1^4 2x\\,dx$.",
   sol:[
    "The integrand is $f(x) = 2x$. We need $F'(x) = 2x$, so choose $F(x) = x^2$.",
    "By FTC Part 2, $\\int_1^4 2x\\,dx = x^2\\Big|_1^4 = 4^2-1^2 = 15$"],
   ans:"$15$"},
  {id:"CN1.2.1-EX9", src:"Course notes 1.2, Example 9", lec:"L04", kind:"example", page:"p. 29",
   q:"Evaluate $\\displaystyle\\int_0^{\\pi/4}\\cos(x)\\,dx$.",
   sol:[
    "The integrand is $f(x) = \\cos(x)$, so choose $F(x) = \\sin(x)$.",
    "$\\int_0^{\\pi/4}\\cos(x)\\,dx = \\sin(x)\\Big|_0^{\\pi/4} = \\sin\\!\\left(\\tfrac\\pi4\\right) - \\sin(0) = \\tfrac1{\\sqrt2}$"],
   ans:"$\\frac1{\\sqrt2}$",
   note:"The notes write the integral without its limits on the solution line; it should read $\\int_0^{\\pi/4}\\cos(x)\\,dx$, as written here."},
  {id:"CN1.2.1-EX10", src:"Course notes 1.2, Example 10", lec:"L04", kind:"example", page:"p. 29",
   q:"An object has velocity $v(t) = t^2$ m/s. What is the net change in position from $t=1$ s to $t=2$ s?",
   sol:[
    "$s(t) = \\frac13t^3$ satisfies $s'(t) = v(t)$.",
    "$\\Delta s = \\int_1^2v(t)\\,dt = \\tfrac13t^3\\Big|_1^2 = \\tfrac13(2^3) - \\tfrac13(1^3) = \\tfrac73$ m"],
   ans:"$\\Delta s = \\frac73$ m",
   note:"The notes give the velocity in m/s$^2$; velocity is in m/s."},
  {id:"CN1.2.1-XR6", src:"Course notes 1.2, Exercise 6", lec:"L04", kind:"exercise", page:"p. 29",
   q:"Evaluate.<br>(a) $\\displaystyle\\int_{-1}^3 5\\,dx$<br>(b) $\\displaystyle\\int_0^2 e^x\\,dx$<br>(c) $\\displaystyle\\int_0^{\\pi/2} -\\sin(x)\\,dx$",
   sol:[
    "(a) $f(x) = 5$, so choose $F(x) = 5x$.",
    "$\\int_{-1}^3 5\\,dx = 5x\\Big|_{-1}^3 = 5(3)-5(-1) = 20$",
    "(b) $f(x) = e^x$, so choose $F(x) = e^x$.",
    "$\\int_0^2e^x\\,dx = e^x\\Big|_0^2 = e^2-e^0 = e^2-1$",
    "(c) $f(x) = -\\sin(x)$, so choose $F(x) = \\cos(x)$.",
    "$\\int_0^{\\pi/2}-\\sin(x)\\,dx = \\cos(x)\\Big|_0^{\\pi/2} = \\cos\\!\\left(\\tfrac\\pi2\\right)-\\cos(0) = 0-1 = -1$"],
   ans:"(a) $20$; (b) $e^2-1$; (c) $-1$"},
  {id:"CN1.2.1-XR7", src:"Course notes 1.2, Exercise 7", lec:"L04", kind:"exercise", page:"p. 29",
   q:"What is the area under the graph of $y = f(x) = x$ from $x=c$ to $x=d$?",
   sol:[
    "The area is $\\int_c^d x\\,dx$. The integrand is $f(x) = x$, so choose $F(x) = \\frac12x^2$.",
    "$\\int_c^dx\\,dx = \\tfrac12x^2\\Big|_c^d = \\tfrac12d^2 - \\tfrac12c^2$"],
   ans:"$\\frac12d^2-\\frac12c^2$"},
  {id:"CN1.2.1-XR8", src:"Course notes 1.2, Exercise 8", lec:"L04", kind:"exercise", page:"p. 29",
   q:"If $Q'(t) = 5t^4$, what is the net change in $Q$ from $t=0$ to $t=2$?",
   sol:[
    "$Q(t) = t^5$ satisfies $Q'(t) = 5t^4$.",
    "$\\Delta Q = \\int_0^2Q'(t)\\,dt = t^5\\Big|_0^2 = 2^5-0^5 = 32$"],
   ans:"$32$"},
  {id:"CN1.2.2-EX11", src:"Course notes 1.2, Example 11", lec:"L05", kind:"example", page:"p. 30",
   q:"Find an antiderivative of $f(x) = x^4$.",
   sol:[
    "$F(x) = \\frac15x^5$ is an antiderivative, since $F'(x) = \\frac15(5x^4) = x^4 = f(x)$.",
    "(Other correct answers include $\\frac15x^5+2$ and $\\frac15x^5-\\sqrt2$; in general $\\frac15x^5+C$.)"],
   ans:"$F(x) = \\frac15x^5$"},
  {id:"CN1.2.2-EX12", src:"Course notes 1.2, Example 12", lec:"L05", kind:"example", page:"p. 30",
   q:"Find an antiderivative of $g(x) = \\sin(x)$.",
   sol:[
    "$G(x) = -\\cos(x)$, since $G'(x) = -(-\\sin(x)) = \\sin(x) = g(x)$."],
   ans:"$G(x) = -\\cos(x)$"},
  {id:"CN1.2.2-EX13", src:"Course notes 1.2, Example 13", lec:"L05", kind:"example", page:"p. 30",
   q:"Find an antiderivative of $h(x) = e^x$.",
   sol:[
    "$H(x) = e^x$, since $H'(x) = e^x = h(x)$."],
   ans:"$H(x) = e^x$"},
  {id:"CN1.2.2-EX14", src:"Course notes 1.2, Example 14", lec:"L05", kind:"example", page:"p. 31",
   q:"Evaluate $\\displaystyle\\int 3x^2\\,dx$.",
   sol:[
    "An antiderivative of $f(x) = 3x^2$ is $F(x) = x^3$, since $F'(x) = f(x)$.",
    "$\\int3x^2\\,dx = x^3 + C$"],
   ans:"$x^3+C$"},
  {id:"CN1.2.2-EX15", src:"Course notes 1.2, Example 15", lec:"L05", kind:"example", page:"p. 31",
   q:"Evaluate $\\displaystyle\\int 3\\,dt$.",
   sol:[
    "The $dt$ tells us the independent variable is $t$. An antiderivative of $f(t) = 3$ is $F(t) = 3t$.",
    "$\\int3\\,dt = 3t+C$"],
   ans:"$3t+C$"},
  {id:"CN1.2.2-XR9", src:"Course notes 1.2, Exercise 9", lec:"L05", kind:"exercise", page:"p. 31",
   q:"Find the indefinite integral and check your answer.<br>(a) $\\displaystyle\\int2x^3\\,dx$<br>(b) $\\displaystyle\\int\\cos(x)\\,dx$<br>(c) $\\displaystyle\\int-2\\,dw$<br>(d) $\\displaystyle\\int(t+1)\\,dt$",
   sol:[
    "(a) $\\int2x^3\\,dx = \\frac{x^4}2 + C$",
    "Check: $\\frac{d}{dx}\\left(\\frac{x^4}2+C\\right) = \\frac42x^3+0 = 2x^3$, which is the integrand.",
    "(b) $\\int\\cos(x)\\,dx = \\sin(x)+C$",
    "Check: $\\frac{d}{dx}(\\sin(x)+C) = \\cos(x)+0 = \\cos(x)$.",
    "(c) $\\int-2\\,dw = -2w+C$",
    "Check: $\\frac{d}{dw}(-2w+C) = -2+0 = -2$.",
    "(d) $\\int(t+1)\\,dt = \\frac{t^2}2+t+C$",
    "Check: $\\frac{d}{dt}\\left(\\frac{t^2}2+t+C\\right) = t+1+0 = t+1$."],
   ans:"(a) $\\frac{x^4}{2}+C$; (b) $\\sin(x)+C$; (c) $-2w+C$; (d) $\\frac{t^2}{2}+t+C$"},
  {id:"CN1.2.2-EX16", src:"Course notes 1.2, Example 16", lec:"L05", kind:"example", page:"p. 32",
   q:"Evaluate $\\displaystyle\\int(x^2+3)^2\\,dx$.",
   sol:[
    "Expand the integrand first:",
    "$\\int(x^2+3)^2\\,dx = \\int(x^4+6x^2+9)\\,dx = \\tfrac15x^5 + 2x^3 + 9x + C$"],
   ans:"$\\frac15x^5+2x^3+9x+C$"},
  {id:"CN1.2.2-XR10", src:"Course notes 1.2, Exercise 10", lec:"L05", kind:"exercise", page:"p. 32",
   q:"Evaluate $\\displaystyle\\int(\\sin^2(x)+\\cos^2(x))\\,dx$.",
   sol:[
    "Since $\\sin^2(x)+\\cos^2(x) = 1$,",
    "$\\int(\\sin^2(x)+\\cos^2(x))\\,dx = \\int1\\,dx = x+C$"],
   ans:"$x+C$"},
  {id:"CN1.2.2-EX17", src:"Course notes 1.2, Example 17", lec:"L05", kind:"example", page:"p. 32",
   q:"Evaluate $\\displaystyle\\int\\frac{t^2-2t^4}{t^4}\\,dt$.",
   sol:[
    "Split the fraction:",
    "$\\int\\dfrac{t^2-2t^4}{t^4}\\,dt = \\int\\left(\\dfrac{t^2}{t^4} - \\dfrac{2t^4}{t^4}\\right)dt = \\int\\left(t^{-2}-2\\right)dt = -\\dfrac1t - 2t + C$"],
   ans:"$-\\frac1t-2t+C$"},
  {id:"CN1.2.2-XR11", src:"Course notes 1.2, Exercise 11", lec:"L05", kind:"exercise", page:"p. 33",
   q:"Evaluate $\\displaystyle\\int\\frac{x+\\sqrt x}{\\sqrt[3]x}\\,dx$.",
   sol:[
    "$\\int\\dfrac{x+x^{1/2}}{x^{1/3}}\\,dx = \\int\\left(\\dfrac{x}{x^{1/3}} + \\dfrac{x^{1/2}}{x^{1/3}}\\right)dx = \\int\\left(x^{2/3}+x^{1/6}\\right)dx$",
    "$= \\dfrac35x^{5/3} + \\dfrac67x^{7/6} + C$"],
   ans:"$\\frac35x^{5/3}+\\frac67x^{7/6}+C$"},
  {id:"CN1.2.3-EX18", src:"Course notes 1.2, Example 18", lec:"L06", kind:"example", page:"p. 33",
   q:"Find all solutions of $\\dfrac{dy}{dx} = \\cos(x)$.",
   sol:[
    "We want all $y$ with $y' = \\cos(x)$:",
    "$y = \\int\\cos(x)\\,dx = \\sin(x)+C$"],
   ans:"$y = \\sin(x)+C$"},
  {id:"CN1.2.3-EX19", src:"Course notes 1.2, Example 19", lec:"L06", kind:"example", page:"p. 33",
   q:"Find all solutions of $\\dfrac{dy}{dt} = 8$.",
   sol:[
    "The notation tells us the independent variable is $t$:",
    "$y = \\int8\\,dt = 8t+C$"],
   ans:"$y = 8t+C$"},
  {id:"CN1.2.3-EX20", src:"Course notes 1.2, Example 20", lec:"L06", kind:"example", page:"p. 33",
   q:"Find all solutions of $\\dfrac{dy}{dx} = \\dfrac{x^2+\\sqrt x}{x}$.",
   sol:[
    "Split the fraction to get terms we can integrate:",
    "$y = \\int\\dfrac{x^2+\\sqrt x}x\\,dx = \\int\\left(\\dfrac{x^2}x + \\dfrac{\\sqrt x}x\\right)dx = \\int(x + x^{-1/2})\\,dx$",
    "$y = \\tfrac12x^2 + 2x^{1/2} + C$"],
   ans:"$y = \\frac12x^2+2x^{1/2}+C$"},
  {id:"CN1.2.3-XR12", src:"Course notes 1.2, Exercise 12", lec:"L06", kind:"exercise", page:"p. 34",
   q:"Find all solutions.<br>(a) $\\dfrac{dy}{dx} = x^2+x+\\dfrac1{x^2}$<br>(b) $\\dfrac{dy}{dt} = -2$<br>(c) $\\dfrac{dy}{dx} = e^x+3$",
   sol:[
    "(a) $y = \\int\\left(x^2+x+x^{-2}\\right)dx = \\frac13x^3+\\frac12x^2-\\frac1x+C$",
    "(b) $y = \\int-2\\,dt = -2t+C$",
    "(c) $y = \\int(e^x+3)\\,dx = e^x+3x+C$"],
   ans:"(a) $y=\\frac13x^3+\\frac12x^2-\\frac1x+C$; (b) $y=-2t+C$; (c) $y=e^x+3x+C$"},
  {id:"CN1.2.3-EX21", src:"Course notes 1.2, Example 21", lec:"L06", kind:"example", page:"p. 34",
   q:"Solve the initial value problem $y' = \\sin(x)$, $y(0) = 5$.",
   sol:[
    "All solutions of $y' = \\sin(x)$: $y = \\int\\sin(x)\\,dx = -\\cos(x)+C$",
    "The initial condition says $y=5$ when $x=0$:",
    "$5 = -\\cos(0)+C \\Rightarrow 5 = -1+C \\Rightarrow C = 6$",
    "So $y(x) = -\\cos(x)+6$."],
   ans:"$y = -\\cos(x)+6$"},
  {id:"CN1.2.3-EX22", src:"Course notes 1.2, Example 22", lec:"L06", kind:"example", page:"p. 35",
   q:"Solve the initial value problem $y' = e^t$, $y(0) = \\pi$.",
   sol:[
    "$y = \\int e^t\\,dt = e^t+C$",
    "The initial condition says $y = \\pi$ when $t = 0$:",
    "$\\pi = e^0+C \\Rightarrow \\pi = 1+C \\Rightarrow C = \\pi-1$",
    "So $y(t) = e^t+\\pi-1$."],
   ans:"$y = e^t+\\pi-1$"},
  {id:"CN1.2.3-XR13", src:"Course notes 1.2, Exercise 13", lec:"L06", kind:"exercise", page:"p. 35",
   q:"Solve the initial value problem.<br>(a) $y' = x$, $y(1) = -3$<br>(b) $y' = e^x$, $y(3) = 2$",
   sol:[
    "(a) $y = \\int x\\,dx = \\frac12x^2+C$",
    "$y=-3$ when $x=1$: $-3 = \\frac12(1)^2+C \\Rightarrow C = -\\frac72$",
    "$y = \\frac12x^2-\\frac72$",
    "(b) $y = \\int e^x\\,dx = e^x+C$",
    "$y=2$ when $x=3$: $2 = e^3+C \\Rightarrow C = 2-e^3$",
    "$y = e^x+2-e^3$"],
   ans:"(a) $y=\\frac12x^2-\\frac72$; (b) $y=e^x+2-e^3$"},
  {id:"CN1.2-P1-a-d", src:"Course notes 1.2, End of Section Problem 1, parts (a) to (d)", lec:"L05", kind:"problem", page:"p. 35",
   q:"Evaluate the indefinite integral.<br>(a) $\\displaystyle\\int(3x-1)\\,dx$<br>(b) $\\displaystyle\\int3x^2\\,dx$<br>(c) $\\displaystyle\\int1\\,dt$<br>(d) $\\displaystyle\\int4t^2\\,dt$",
   sol:[
    "(a) $\\int(3x-1)\\,dx = 3\\cdot\\frac{x^2}{2} - x + C = \\frac32x^2 - x + C$",
    "Check: $\\frac{d}{dx}\\left(\\frac32x^2-x+C\\right) = 3x-1$.",
    "(b) $\\int3x^2\\,dx = 3\\cdot\\frac{x^3}{3} + C = x^3+C$",
    "Check: $\\frac{d}{dx}(x^3+C) = 3x^2$.",
    "(c) $\\int1\\,dt = t+C$",
    "Check: $\\frac{d}{dt}(t+C) = 1$.",
    "(d) $\\int4t^2\\,dt = 4\\cdot\\frac{t^3}{3}+C = \\frac{4t^3}3+C$",
    "Check: $\\frac{d}{dt}\\left(\\frac{4t^3}{3}+C\\right) = 4t^2$."],
   ans:"(a) $\\frac32x^2-x+C$; (b) $x^3+C$; (c) $t+C$; (d) $\\frac{4t^3}{3}+C$",
   note:"The official solutions give only the final answers; the working is added here."},
  {id:"CN1.2-P1-e-h", src:"Course notes 1.2, End of Section Problem 1, parts (e) to (h)", lec:"L05", kind:"problem", page:"p. 35",
   q:"Evaluate the indefinite integral.<br>(e) $\\displaystyle\\int(y^5+1)\\,dy$<br>(f) $\\displaystyle\\int\\frac1{r^2}\\,dr$<br>(g) $\\displaystyle\\int2\\cos(s)\\,ds$<br>(h) $\\displaystyle\\int e^t\\,dt$",
   sol:[
    "(e) $\\int(y^5+1)\\,dy = \\frac{y^6}6+y+C$",
    "Check: $\\frac{d}{dy}\\left(\\frac{y^6}6+y+C\\right) = y^5+1$.",
    "(f) $\\int r^{-2}\\,dr = \\frac{r^{-1}}{-1}+C = -\\frac1r+C$",
    "Check: $\\frac{d}{dr}\\left(-r^{-1}+C\\right) = r^{-2}$.",
    "(g) $\\int2\\cos(s)\\,ds = 2\\sin(s)+C$",
    "Check: $\\frac{d}{ds}(2\\sin(s)+C) = 2\\cos(s)$.",
    "(h) $\\int e^t\\,dt = e^t+C$",
    "Check: $\\frac{d}{dt}(e^t+C) = e^t$."],
   ans:"(e) $\\frac{y^6}{6}+y+C$; (f) $-\\frac1r+C$; (g) $2\\sin(s)+C$; (h) $e^t+C$",
   note:"The official solutions give only the final answers; the working is added here."},
  {id:"CN1.2-P2-a-d", src:"Course notes 1.2, End of Section Problem 2, parts (a) to (d)", lec:"L05", kind:"problem", page:"p. 35",
   q:"Evaluate the indefinite integral.<br>(a) $\\displaystyle\\int\\frac1{\\sqrt x}\\,dx$<br>(b) $\\displaystyle\\int(5\\sin(x)+2)\\,dx$<br>(c) $\\displaystyle\\int e^{kt}\\,dt$, where $k\\neq 0$ is a constant<br>(d) $\\displaystyle\\int4e^x\\,dx$",
   sol:[
    "(a) $\\int x^{-1/2}\\,dx = \\frac{x^{1/2}}{1/2}+C = 2\\sqrt x+C$",
    "Check: $\\frac{d}{dx}(2x^{1/2}+C) = x^{-1/2}$.",
    "(b) $\\int(5\\sin(x)+2)\\,dx = 5(-\\cos(x))+2x+C = -5\\cos(x)+2x+C$",
    "Check: $\\frac{d}{dx}(-5\\cos(x)+2x+C) = 5\\sin(x)+2$.",
    "(c) By the Chain Rule, $\\frac{d}{dt}e^{kt} = ke^{kt}$, so $\\frac{d}{dt}\\left(\\frac1ke^{kt}\\right) = e^{kt}$.",
    "$\\int e^{kt}\\,dt = \\dfrac{e^{kt}}k+C$",
    "(d) $\\int4e^x\\,dx = 4e^x+C$",
    "Check: $\\frac{d}{dx}(4e^x+C) = 4e^x$."],
   ans:"(a) $2\\sqrt x+C$; (b) $-5\\cos(x)+2x+C$; (c) $\\frac{e^{kt}}{k}+C$; (d) $4e^x+C$",
   note:"Part (c) uses the reverse chain rule, which the lectures had not covered at this point. The official solutions give only the final answers; the working is added here."},
  {id:"CN1.2-P2-e-g", src:"Course notes 1.2, End of Section Problem 2, parts (e) to (g)", lec:"L05", kind:"problem", page:"p. 35",
   q:"Evaluate the indefinite integral.<br>(e) $\\displaystyle\\int0\\,dw$<br>(f) $\\displaystyle\\int-2\\sin(3x)\\,dx$<br>(g) $\\displaystyle\\int e^{x/2}\\,dx$",
   sol:[
    "(e) The derivative of any constant is 0, so $\\int0\\,dw = C$.",
    "(f) By the Chain Rule, $\\frac{d}{dx}\\cos(3x) = -3\\sin(3x)$, so $\\frac{d}{dx}\\left(\\frac23\\cos(3x)\\right) = -2\\sin(3x)$.",
    "$\\int-2\\sin(3x)\\,dx = \\frac23\\cos(3x)+C$",
    "(g) By the Chain Rule, $\\frac{d}{dx}e^{x/2} = \\frac12e^{x/2}$, so $\\frac{d}{dx}\\left(2e^{x/2}\\right) = e^{x/2}$.",
    "$\\int e^{x/2}\\,dx = 2e^{x/2}+C$"],
   ans:"(e) $C$; (f) $\\frac23\\cos(3x)+C$; (g) $2e^{x/2}+C$",
   note:"Parts (f) and (g) use the reverse chain rule, which the lectures had not covered at this point. The official solutions give only the final answers; the working is added here."},
  {id:"CN1.2-P3", src:"Course notes 1.2, End of Section Problem 3", lec:"L06", kind:"problem", page:"p. 36",
   q:"Find all solutions of the given differential equation.<br>(a) $\\dfrac{dy}{dx} = x$<br>(b) $\\dfrac{dy}{dx} = x^3+5$<br>(c) $\\dfrac{dy}{dx} = 4\\sqrt x$<br>(d) $\\dfrac{dy}{dx} = x^2+e^x$<br>(e) $\\dfrac{dy}{dx} = 3\\sin(x)-1$<br>(f) $\\dfrac{dy}{dx} = -x^{-3}$",
   sol:[
    "(a) $y = \\int x\\,dx = \\frac12x^2+C$",
    "(b) $y = \\int(x^3+5)\\,dx = \\frac14x^4+5x+C$",
    "(c) $y = \\int4x^{1/2}\\,dx = 4\\cdot\\frac23x^{3/2}+C = \\frac83x^{3/2}+C$",
    "(d) $y = \\int(x^2+e^x)\\,dx = \\frac13x^3+e^x+C$",
    "(e) $y = \\int(3\\sin(x)-1)\\,dx = -3\\cos(x)-x+C$",
    "(f) $y = \\int-x^{-3}\\,dx = -\\frac{x^{-2}}{-2}+C = \\frac12x^{-2}+C$"],
   ans:"(a) $y=\\frac12x^2+C$; (b) $y=\\frac14x^4+5x+C$; (c) $y=\\frac83x^{3/2}+C$; (d) $y=\\frac13x^3+e^x+C$; (e) $y=-3\\cos(x)-x+C$; (f) $y=\\frac12x^{-2}+C$"},
  {id:"CN1.2-P4", src:"Course notes 1.2, End of Section Problem 4", lec:"L06", kind:"problem", page:"p. 36",
   q:"Solve the initial value problem.<br>(a) $\\dfrac{dy}{dx} = x$, $y(1) = 3$<br>(b) $\\dfrac{dy}{dx} = x$, $y(1) = -1$<br>(c) $\\dfrac{dy}{dx} = 1$, $y(\\pi) = \\pi$<br>(d) $\\dfrac{dy}{dx} = x^{-1/3}$, $y(1) = 5$<br>(e) $\\dfrac{dy}{dx} = \\cos(x)$, $y(\\pi) = 2$",
   sol:[
    "(a) $y = \\int x\\,dx = \\frac{x^2}2+C$",
    "$y=3$ when $x=1$: $3 = \\frac{1^2}2+C \\Rightarrow C = 3-\\frac12 = \\frac52$",
    "$y = \\frac{x^2}2+\\frac52$",
    "(b) $y = \\int x\\,dx = \\frac{x^2}2+C$",
    "$y=-1$ when $x=1$: $-1 = \\frac{1^2}2+C \\Rightarrow C = -1-\\frac12 = -\\frac32$",
    "$y = \\frac{x^2}2-\\frac32$",
    "(c) $y = \\int1\\,dx = x+C$",
    "$y=\\pi$ when $x=\\pi$: $\\pi = \\pi+C \\Rightarrow C = 0$",
    "$y = x$",
    "(d) $y = \\int x^{-1/3}\\,dx = \\frac32x^{2/3}+C$",
    "$y=5$ when $x=1$: $5 = \\frac32+C \\Rightarrow C = \\frac72$",
    "$y = \\frac32x^{2/3}+\\frac72$",
    "(e) $y = \\int\\cos(x)\\,dx = \\sin(x)+C$",
    "$y=2$ when $x=\\pi$: $2 = \\sin(\\pi)+C \\Rightarrow C = 2$",
    "$y = \\sin(x)+2$"],
   ans:"(a) $y=\\frac{x^2}{2}+\\frac52$; (b) $y=\\frac{x^2}{2}-\\frac32$; (c) $y=x$; (d) $y=\\frac32x^{2/3}+\\frac72$; (e) $y=\\sin(x)+2$"},
  {id:"CN1.2-P5", src:"Course notes 1.2, End of Section Problem 5", lec:"L04", kind:"problem", page:"p. 36",
   q:"Write the definite integral which represents the area under the graph of the given function between the given points.<br>(a) $f(x) = x+5$ from $x=-1$ to $x=3$<br>(b) $f(x) = \\cos(x)$ from $x=0$ to $x=\\pi$<br>(c) $f(x) = e^x$ from $x=-2$ to $x=-1$",
   sol:[
    "(a) $\\displaystyle\\int_{-1}^3(x+5)\\,dx$",
    "(b) $\\displaystyle\\int_0^\\pi\\cos(x)\\,dx$",
    "(c) $\\displaystyle\\int_{-2}^{-1}e^x\\,dx$"],
   ans:"(a) $\\int_{-1}^3(x+5)\\,dx$; (b) $\\int_0^\\pi\\cos(x)\\,dx$; (c) $\\int_{-2}^{-1}e^x\\,dx$",
   note:"In (b), $\\cos(x)<0$ on $\\left(\\frac\\pi2,\\pi\\right)$, so the integral is a signed area; its value is 0 (see Problem 7(e))."},
  {id:"CN1.2-P6", src:"Course notes 1.2, End of Section Problem 6", lec:"L04", kind:"problem", page:"p. 36",
   q:"Evaluate the definite integral.<br>(a) $\\displaystyle\\int_0^2 1\\,dx$<br>(b) $\\displaystyle\\int_0^3x\\,dx$<br>(c) $\\displaystyle\\int_0^6t\\,dt$<br>(d) $\\displaystyle\\int_0^xt\\,dt$<br>(e) $\\displaystyle\\int_1^23x^2\\,dx$<br>(f) $\\displaystyle\\int_0^\\pi\\sin(\\theta)\\,d\\theta$",
   sol:[
    "(a) An antiderivative is $F(x) = x$.",
    "$\\int_0^2 1\\,dx = x\\Big|_0^2 = 2-0 = 2$",
    "(b) An antiderivative is $F(x) = \\frac12x^2$.",
    "$\\int_0^3x\\,dx = \\frac12x^2\\Big|_0^3 = \\frac{3^2}2-0 = \\frac92$",
    "(c) An antiderivative is $F(t) = \\frac12t^2$.",
    "$\\int_0^6t\\,dt = \\frac12t^2\\Big|_0^6 = \\frac{6^2}2-0 = 18$",
    "(d) As in (c), $F(t) = \\frac12t^2$.",
    "$\\int_0^xt\\,dt = \\frac12t^2\\Big|_0^x = \\frac{x^2}2-0 = \\frac{x^2}2$",
    "A definite integral with a variable limit is a function: here it gives the net change from 0 to $x$.",
    "(e) An antiderivative is $F(x) = x^3$.",
    "$\\int_1^23x^2\\,dx = x^3\\Big|_1^2 = 2^3-1^3 = 7$",
    "(f) An antiderivative is $F(\\theta) = -\\cos(\\theta)$.",
    "$\\int_0^\\pi\\sin(\\theta)\\,d\\theta = -\\cos(\\theta)\\Big|_0^\\pi = -\\cos(\\pi)-(-\\cos(0)) = 1+1 = 2$"],
   ans:"(a) $2$; (b) $\\frac92$; (c) $18$; (d) $\\frac{x^2}{2}$; (e) $7$; (f) $2$"},
  {id:"CN1.2-P7", src:"Course notes 1.2, End of Section Problem 7", lec:"L04", kind:"problem", page:"p. 36",
   q:"Given $f'(x)$, use a definite integral to find the net change in $f$ from $x=c$ to $x=d$.<br>(a) $f'(x) = x^2$, $c=1$, $d=2$<br>(b) $f'(x) = \\sqrt x$, $c=1$, $d=4$<br>(c) $f'(x) = \\cos(x)$, $c=0$, $d=\\frac\\pi2$<br>(d) $f'(x) = \\cos(x)$, $c=\\frac\\pi2$, $d=\\pi$<br>(e) $f'(x) = \\cos(x)$, $c=0$, $d=\\pi$",
   sol:[
    "(a) An antiderivative is $f(x) = \\frac13x^3$.",
    "$\\Delta f = \\int_1^2x^2\\,dx = \\frac13x^3\\Big|_1^2 = \\frac83-\\frac13 = \\frac73$",
    "(b) An antiderivative is $f(x) = \\frac23x^{3/2}$.",
    "$\\Delta f = \\int_1^4\\sqrt x\\,dx = \\frac23x^{3/2}\\Big|_1^4 = \\frac23(4)^{3/2}-\\frac23(1)^{3/2} = \\frac{16}3-\\frac23 = \\frac{14}3$",
    "(c) An antiderivative is $f(x) = \\sin(x)$.",
    "$\\Delta f = \\int_0^{\\pi/2}\\cos(x)\\,dx = \\sin(x)\\Big|_0^{\\pi/2} = \\sin\\!\\left(\\frac\\pi2\\right)-\\sin(0) = 1$",
    "(d) $\\Delta f = \\int_{\\pi/2}^\\pi\\cos(x)\\,dx = \\sin(x)\\Big|_{\\pi/2}^\\pi = \\sin(\\pi)-\\sin\\!\\left(\\frac\\pi2\\right) = -1$",
    "(e) $\\Delta f = \\int_0^\\pi\\cos(x)\\,dx = \\sin(x)\\Big|_0^\\pi = \\sin(\\pi)-\\sin(0) = 0$"],
   ans:"(a) $\\frac73$; (b) $\\frac{14}{3}$; (c) $1$; (d) $-1$; (e) $0$"},
  {id:"CN1.2-P8", src:"Course notes 1.2, End of Section Problem 8", lec:"L04", kind:"problem", page:"p. 36",
   q:"Assume the rate of change of a quantity $F(t)$ is $f(t) = \\dfrac1t$ for $1\\le t\\le3$. Use the left Riemann sum with $n=4$ to approximate the net change in $F$ from $t=1$ to $t=3$.",
   sol:[
    "$\\Delta t = \\dfrac{b-a}n = \\dfrac{3-1}4 = \\dfrac12$ and $t_i = 1+\\dfrac i2$ for $0\\le i\\le3$, so $t_0=1$, $t_1=1.5$, $t_2=2$, $t_3=2.5$.",
    "$\\Delta F \\approx \\dfrac1{t_0}\\Delta t + \\dfrac1{t_1}\\Delta t + \\dfrac1{t_2}\\Delta t + \\dfrac1{t_3}\\Delta t = 1\\cdot\\dfrac12 + \\dfrac23\\cdot\\dfrac12 + \\dfrac12\\cdot\\dfrac12 + \\dfrac25\\cdot\\dfrac12$",
    "$= \\dfrac12+\\dfrac13+\\dfrac14+\\dfrac15 = \\dfrac{77}{60}$"],
   ans:"$\\Delta F\\approx\\frac{77}{60}$"},
  {id:"CN1.2-P9", src:"Course notes 1.2, End of Section Problem 9", lec:"L04", kind:"problem", page:"p. 36",
   q:"Let $f(x) = \\displaystyle\\int_0^xg(t)\\,dt$. Use the table to approximate $f(2)$ using 3 subdivisions.<table class=\"cn-table\"><tr><th>$t$</th><td>0</td><td>$\\frac13$</td><td>$\\frac23$</td><td>1</td><td>$\\frac43$</td><td>$\\frac53$</td></tr><tr><th>$g(t)$</th><td>$-1$</td><td>$-2$</td><td>$-4$</td><td>$-2$</td><td>$-3$</td><td>0</td></tr></table>",
   sol:[
    "$\\Delta t = \\dfrac{2-0}3 = \\dfrac23$ and $t_i = \\dfrac{2i}3$, so $t_0 = 0$, $t_1 = \\frac23$, $t_2 = \\frac43$.",
    "$f(2)\\approx g(0)\\Delta t + g\\!\\left(\\tfrac23\\right)\\Delta t + g\\!\\left(\\tfrac43\\right)\\Delta t = -1\\cdot\\tfrac23 + (-4)\\cdot\\tfrac23 + (-3)\\cdot\\tfrac23 = -\\tfrac{16}3$"],
   ans:"$f(2)\\approx -\\frac{16}{3}$",
   note:"The table values at $t=\\frac13$, $1$ and $\\frac53$ are not used with 3 subdivisions."},
  {id:"CN1.2-P10", src:"Course notes 1.2, End of Section Problem 10", lec:"L04", kind:"problem", page:"p. 36",
   q:"Assume a balloon's volume is changing at a rate of 3 cm$^3$/s from $t=1$ s to $t=3$ s. Use a definite integral to show that the net change in volume is 6 cm$^3$.",
   sol:[
    "$V'(t) = 3$ cm$^3$/s, and an antiderivative is $V(t) = 3t$.",
    "$\\Delta V = \\int_1^33\\,dt = 3t\\Big|_1^3 = 3(3)-3(1) = 9-3 = 6$ cm$^3$"],
   ans:"$\\int_1^3 3\\,dt = 6$ cm$^3$"},
  {id:"CN1.2-P11", src:"Course notes 1.2, End of Section Problem 11", lec:"L04", kind:"problem", page:"p. 36",
   q:"The rate of rainfall in mm/h can be modelled by $r(t) = 3\\left(1-\\cos\\!\\left(\\dfrac{2\\pi t}{24}\\right)\\right)$, where $t$ is the number of hours after midnight. What does $\\displaystyle\\int_0^{24}r(t)\\,dt$ represent?",
   sol:[
    "$r(t)$ is the rate of rainfall in mm per hour, so the integral of the rate from $t=0$ to $t=24$ is the total amount of rainfall over the day, in mm."],
   ans:"The total rainfall (mm) over the 24 hour day"},
  {id:"CN1.2-P12", src:"Course notes 1.2, End of Section Problem 12", lec:"L04", kind:"problem", page:"p. 36",
   q:"If an object accelerates at $3t^2$ m/s$^2$ from $t=0$ s to $t=2$ s, what is the net change in velocity?",
   sol:[
    "Acceleration is the rate of change of velocity. An antiderivative of $a(t) = 3t^2$ is $v(t) = t^3$.",
    "$\\Delta v = \\int_0^23t^2\\,dt = t^3\\Big|_0^2 = 2^3-0^3 = 8$ m/s"],
   ans:"$\\Delta v = 8$ m/s"},
  {id:"CN1.2-P13", src:"Course notes 1.2, End of Section Problem 13", lec:"L04", kind:"problem", page:"p. 36",
   q:"The velocity of a particle is $v(t) = 3t^2-6t$ m/s. Determine the change in position from $t=2$ to $t=3$.",
   sol:[
    "The change in position is $\\int_2^3v(t)\\,dt$. An antiderivative of $v$ is $s(t) = t^3-3t^2$.",
    "$\\int_2^3(3t^2-6t)\\,dt = \\left(t^3-3t^2\\right)\\Big|_2^3 = (3^3-3(3)^2)-(2^3-3(2)^2) = 0-(-4) = 4$ m"],
   ans:"$4$ m"},
  {id:"CN1.2-P14", src:"Course notes 1.2, End of Section Problem 14", lec:"L06", kind:"problem", page:"p. 36",
   q:"If an object has initial position $s(0) = s_0$, initial velocity $s'(0) = v_0$, and constant acceleration $s''(t) = a$, show that its position at time $t$ is $s(t) = \\frac12at^2 + v_0t + s_0$.",
   sol:[
    "$s''(t) = a$ is a DE for $s'(t)$. All functions $s'(t)$ with derivative $a$: $s'(t) = \\int a\\,dt = at+b$.",
    "Using $s'(0) = v_0$: $v_0 = a(0)+b$, so $b = v_0$ and $s'(t) = at+v_0$.",
    "All functions $s(t)$ with derivative $at+v_0$: $s(t) = \\int(at+v_0)\\,dt = \\tfrac12at^2 + v_0t + c$",
    "Using $s(0) = s_0$: $s_0 = \\frac12a(0)^2 + v_0(0) + c$, so $c = s_0$.",
    "Hence $s(t) = \\frac12at^2+v_0t+s_0$, as required."],
   ans:"$s(t) = \\frac12at^2+v_0t+s_0$"},
  {id:"CN1-ECP1-a-d", src:"Course notes Ch. 1, End of Chapter Problem 1, parts (a) to (d)", lec:"L01", kind:"chapter", page:"p. 37",
   q:"Determine the second derivative of each function.<br>(a) $f(x) = 3x^2+2x-1$<br>(b) $g(x) = \\sin(x)$<br>(c) $h(t) = e^{2t}$<br>(d) $g(t) = (1+t)^{1/4}$",
   sol:[
    "(a) $f'(x) = 6x+2$",
    "$f''(x) = 6$",
    "(b) $g'(x) = \\cos(x)$",
    "$g''(x) = -\\sin(x)$",
    "(c) By the Chain Rule, $h'(t) = 2e^{2t}$",
    "$h''(t) = 4e^{2t}$",
    "(d) $g'(t) = \\frac14(1+t)^{-3/4}$",
    "$g''(t) = \\frac14\\cdot\\left(-\\frac34\\right)(1+t)^{-7/4} = -\\frac3{16}(1+t)^{-7/4}$"],
   ans:"(a) $6$; (b) $-\\sin(x)$; (c) $4e^{2t}$; (d) $-\\frac3{16}(1+t)^{-7/4}$"},
  {id:"CN1-ECP1-e-g", src:"Course notes Ch. 1, End of Chapter Problem 1, parts (e) to (g)", lec:"L01", kind:"chapter", page:"p. 37",
   q:"Determine the second derivative of each function.<br>(e) $m(w) = \\dfrac{w}{2w+1}$<br>(f) $f(x) = \\cos(x^2)$<br>(g) $f(x) = \\dfrac1{x^2+1}$",
   sol:[
    "(e) By the Quotient Rule, $m'(w) = \\dfrac{1(2w+1)-2w}{(2w+1)^2} = \\dfrac1{(2w+1)^2}$",
    "Write $m'(w) = (2w+1)^{-2}$. By the Chain Rule, $m''(w) = -2(2w+1)^{-3}\\cdot2 = \\dfrac{-4}{(2w+1)^3}$",
    "(f) $f'(x) = -\\sin(x^2)\\cdot(2x) = -2x\\sin(x^2)$",
    "By the Product Rule, $f''(x) = -2\\sin(x^2) + (-2x)\\cos(x^2)(2x) = -2\\sin(x^2)-4x^2\\cos(x^2)$",
    "(g) $f'(x) = -(x^2+1)^{-2}(2x) = \\dfrac{-2x}{(x^2+1)^2}$",
    "By the Quotient Rule, $f''(x) = \\dfrac{-2(x^2+1)^2 - (-2x)\\cdot2(x^2+1)(2x)}{(x^2+1)^4} = \\dfrac{-2(x^2+1)+8x^2}{(x^2+1)^3} = \\dfrac{6x^2-2}{(x^2+1)^3}$"],
   ans:"(e) $\\frac{-4}{(2w+1)^3}$; (f) $-2\\sin(x^2)-4x^2\\cos(x^2)$; (g) $\\frac{6x^2-2}{(x^2+1)^3}$"},
  {id:"CN1-ECP2", src:"Course notes Ch. 1, End of Chapter Problem 2", lec:"L02", kind:"chapter", page:"p. 37",
   q:"Find the equation of the tangent line of the function at the given $a$.<br>(a) $f(x) = \\sin(x)$, $a=0$<br>(b) $f(x) = x^2-\\frac35x+\\frac17$, $a=0$<br>(c) $f(x) = (1+x)^{2/3}$, $a=0$<br>(d) $f(x) = (1+x)^{-3/4}$, $a=0$<br>(e) $f(x) = \\dfrac1{x^2}$, $a=-1$<br>(f) $f(x) = e^{x^2}$, $a=1$",
   sol:[
    "(a) $f'(x) = \\cos(x)$",
    "$y = f(0)+f'(0)(x-0) = 0+1(x-0) = x$",
    "(b) $f'(x) = 2x-\\frac35$",
    "$y = f(0)+f'(0)(x-0) = \\frac17-\\frac35(x-0) = \\frac17-\\frac35x$",
    "(c) $f'(x) = \\frac23(1+x)^{-1/3}$",
    "$y = f(0)+f'(0)(x-0) = 1+\\frac23(x-0) = 1+\\frac23x$",
    "(d) $f'(x) = -\\frac34(1+x)^{-7/4}$",
    "$y = f(0)+f'(0)(x-0) = 1-\\frac34(x-0) = 1-\\frac34x$",
    "(e) $f'(x) = -\\dfrac2{x^3}$, so $f'(-1) = 2$",
    "$y = f(-1)+f'(-1)(x-(-1)) = 1+2(x+1)$",
    "(f) $f'(x) = 2xe^{x^2}$, so $f'(1) = 2e$",
    "$y = f(1)+f'(1)(x-1) = e+2e(x-1)$"],
   ans:"(a) $y=x$; (b) $y=\\frac17-\\frac35x$; (c) $y=1+\\frac23x$; (d) $y=1-\\frac34x$; (e) $y=1+2(x+1)$; (f) $y=e+2e(x-1)$"},
  {id:"CN1-ECP3-a-d", src:"Course notes Ch. 1, End of Chapter Problem 3, parts (a) to (d)", lec:"L02", kind:"chapter", page:"p. 37",
   q:"Use the tangent line of the function at $a$ to approximate the given value.<br>(a) $f(x) = \\sqrt x$, $a=1$; approximate $\\sqrt3$<br>(b) $f(x) = \\sqrt x$, $a=4$; approximate $\\sqrt3$<br>(c) $f(x) = \\cos(x)$, $a=0$; approximate $\\cos(0.1)$<br>(d) $f(x) = (1+x)^{1/3}$, $a=0$; approximate $(1.001)^{1/3}$",
   sol:[
    "(a) $f'(x) = \\frac12x^{-1/2}$. Tangent line: $y = f(1)+f'(1)(x-1) = 1+\\frac12(x-1)$",
    "Take $x=3$: $\\sqrt3 = f(3)\\approx 1+\\frac12(3-1) = 2$",
    "(b) Tangent line: $y = f(4)+f'(4)(x-4) = 2+\\frac14(x-4)$",
    "Take $x=3$: $\\sqrt3 = f(3)\\approx 2+\\frac14(3-4) = \\frac74$",
    "(c) $f'(x) = -\\sin(x)$. Tangent line: $y = 1+0(x-0) = 1$",
    "$\\cos(0.1) = f(0.1)\\approx 1$",
    "(d) $f'(x) = \\frac13(1+x)^{-2/3}$. Tangent line: $y = 1+\\frac13x$",
    "Take $x = 0.001$: $(1.001)^{1/3}\\approx 1+\\frac13\\cdot\\frac1{1000} = \\frac{3001}{3000}$"],
   ans:"(a) $2$; (b) $\\frac74$; (c) $1$; (d) $\\frac{3001}{3000}$"},
  {id:"CN1-ECP3-e-h", src:"Course notes Ch. 1, End of Chapter Problem 3, parts (e) to (h)", lec:"L02", kind:"chapter", page:"p. 37",
   q:"Use the tangent line of the function at $a$ to approximate the given value.<br>(e) $f(x) = (1+x)^{-1/4}$, $a=0$; approximate $(1.01)^{-1/4}$<br>(f) $f(x) = (1+x)^{2/5}$, $a=0$; approximate $(0.99)^{2/5}$<br>(g) $f(x) = \\dfrac1{x^2}$, $a=1$; approximate $\\dfrac1{(1.01)^2}$<br>(h) $f(x) = e^x$, $a=0$; approximate $e^2$",
   sol:[
    "(e) $f'(x) = -\\frac14(1+x)^{-5/4}$. Tangent line: $y = 1-\\frac14x$",
    "Take $x = 0.01$: $(1.01)^{-1/4}\\approx 1-\\frac14\\cdot\\frac1{100} = \\frac{399}{400}$",
    "(f) $f'(x) = \\frac25(1+x)^{-3/5}$. Tangent line: $y = 1+\\frac25x$",
    "Take $x=-0.01$: $(0.99)^{2/5}\\approx 1+\\frac25\\left(-\\frac1{100}\\right) = \\frac{498}{500} = \\frac{249}{250}$",
    "(g) $f'(x) = -\\dfrac2{x^3}$. Tangent line: $y = f(1)+f'(1)(x-1) = 1-2(x-1)$",
    "Take $x = 1.01$: $\\frac1{(1.01)^2} = f(1.01)\\approx 1-2(1.01-1) = 1-\\frac2{100} = \\frac{49}{50}$",
    "(h) $f'(x) = e^x$. Tangent line: $y = 1+1(x-0) = 1+x$",
    "Take $x=2$: $e^2 = f(2)\\approx 1+2 = 3$"],
   ans:"(e) $\\frac{399}{400}$; (f) $\\frac{249}{250}$; (g) $\\frac{49}{50}$; (h) $3$",
   note:"In (h) the approximation is poor ($e^2\\approx 7.39$) because $x=2$ is far from $a=0$; the official solution does not comment on this."},
  {id:"CN1-ECP4-a-d", src:"Course notes Ch. 1, End of Chapter Problem 4, parts (a) to (d)", lec:"L03", kind:"chapter", page:"p. 37",
   q:"Determine the differential $du$.<br>(a) $u = 3x^3+4x+1$<br>(b) $u = \\dfrac3x$<br>(c) $u = \\sqrt x$<br>(d) $u = e^{3x}$",
   sol:[
    "(a) $du = u'(x)\\,dx = (9x^2+4)\\,dx$",
    "(b) $du = u'(x)\\,dx = -\\dfrac3{x^2}\\,dx$",
    "(c) $du = u'(x)\\,dx = \\dfrac1{2\\sqrt x}\\,dx$",
    "(d) $du = u'(x)\\,dx = 3e^{3x}\\,dx$"],
   ans:"(a) $du=(9x^2+4)\\,dx$; (b) $du=-\\frac3{x^2}\\,dx$; (c) $du=\\frac1{2\\sqrt x}\\,dx$; (d) $du=3e^{3x}\\,dx$"},
  {id:"CN1-ECP4-e-g", src:"Course notes Ch. 1, End of Chapter Problem 4, parts (e) to (g)", lec:"L03", kind:"chapter", page:"p. 37",
   q:"Determine the differential $du$.<br>(e) $u = x^2+1$<br>(f) $u = \\sqrt{x^2+1}$<br>(g) $u = \\sin(x^2+x)$",
   sol:[
    "(e) $du = u'(x)\\,dx = 2x\\,dx$",
    "(f) $du = u'(x)\\,dx = \\frac12(x^2+1)^{-1/2}\\cdot2x\\,dx = \\dfrac{x}{\\sqrt{x^2+1}}\\,dx$",
    "(g) $du = u'(x)\\,dx = \\cos(x^2+x)(2x+1)\\,dx$"],
   ans:"(e) $du=2x\\,dx$; (f) $du=\\frac{x}{\\sqrt{x^2+1}}\\,dx$; (g) $du=(2x+1)\\cos(x^2+x)\\,dx$"},
  {id:"CN1-ECP5-a-d", src:"Course notes Ch. 1, End of Chapter Problem 5, parts (a) to (d)", lec:"L05", kind:"chapter", page:"p. 37",
   q:"Evaluate the indefinite integral.<br>(a) $\\displaystyle\\int3\\,dt$<br>(b) $\\displaystyle\\int(2x+5)\\,dx$<br>(c) $\\displaystyle\\int(x^2+1)\\,dx$<br>(d) $\\displaystyle\\int\\frac3{x^2}\\,dx$",
   sol:[
    "(a) $\\int3\\,dt = 3t+C$",
    "(b) $\\int(2x+5)\\,dx = 2\\cdot\\frac{x^2}2+5x+C = x^2+5x+C$",
    "(c) $\\int(x^2+1)\\,dx = \\frac13x^3+x+C$",
    "(d) $\\int3x^{-2}\\,dx = 3\\cdot\\frac{x^{-1}}{-1}+C = -\\frac3x+C$"],
   ans:"(a) $3t+C$; (b) $x^2+5x+C$; (c) $\\frac13x^3+x+C$; (d) $-\\frac3x+C$",
   note:"The official solutions give only the final answers; the working is added here."},
  {id:"CN1-ECP5-e-h", src:"Course notes Ch. 1, End of Chapter Problem 5, parts (e) to (h)", lec:"L05", kind:"chapter", page:"p. 37",
   q:"Evaluate the indefinite integral.<br>(e) $\\displaystyle\\int4\\sin(x)\\,dx$<br>(f) $\\displaystyle\\int\\frac1{\\sqrt x}\\,dx$<br>(g) $\\displaystyle\\int\\cos(2x)\\,dx$<br>(h) $\\displaystyle\\int\\frac2{x^3}\\,dx$",
   sol:[
    "(e) $\\int4\\sin(x)\\,dx = 4(-\\cos(x))+C = -4\\cos(x)+C$",
    "(f) $\\int x^{-1/2}\\,dx = \\frac{x^{1/2}}{1/2}+C = 2\\sqrt x+C$",
    "(g) By the Chain Rule, $\\frac{d}{dx}\\sin(2x) = 2\\cos(2x)$, so $\\frac{d}{dx}\\left(\\frac12\\sin(2x)\\right) = \\cos(2x)$.",
    "$\\int\\cos(2x)\\,dx = \\frac12\\sin(2x)+C$",
    "(h) $\\int2x^{-3}\\,dx = 2\\cdot\\frac{x^{-2}}{-2}+C = -\\frac1{x^2}+C$"],
   ans:"(e) $-4\\cos(x)+C$; (f) $2\\sqrt x+C$; (g) $\\frac12\\sin(2x)+C$; (h) $-\\frac1{x^2}+C$",
   note:"Part (g) uses the reverse chain rule, which the lectures had not covered at this point. The official solutions give only the final answers; the working is added here."},
  {id:"CN1-ECP5-i-l", src:"Course notes Ch. 1, End of Chapter Problem 5, parts (i) to (l)", lec:"L05", kind:"chapter", page:"p. 37",
   q:"Evaluate the indefinite integral.<br>(i) $\\displaystyle\\int x^{-1/3}\\,dx$<br>(j) $\\displaystyle\\int\\sin\\!\\left(\\frac x3\\right)dx$<br>(k) $\\displaystyle\\int e^{2x}\\,dx$<br>(l) $\\displaystyle\\int x^{2/3}\\,dx$",
   sol:[
    "(i) $\\int x^{-1/3}\\,dx = \\frac{x^{2/3}}{2/3}+C = \\frac32x^{2/3}+C$",
    "(j) By the Chain Rule, $\\frac{d}{dx}\\cos\\!\\left(\\frac x3\\right) = -\\frac13\\sin\\!\\left(\\frac x3\\right)$, so $\\frac{d}{dx}\\left(-3\\cos\\!\\left(\\frac x3\\right)\\right) = \\sin\\!\\left(\\frac x3\\right)$.",
    "$\\int\\sin\\!\\left(\\frac x3\\right)dx = -3\\cos\\!\\left(\\frac x3\\right)+C$",
    "(k) By the Chain Rule, $\\frac{d}{dx}e^{2x} = 2e^{2x}$, so $\\frac{d}{dx}\\left(\\frac12e^{2x}\\right) = e^{2x}$.",
    "$\\int e^{2x}\\,dx = \\frac12e^{2x}+C$",
    "(l) $\\int x^{2/3}\\,dx = \\frac{x^{5/3}}{5/3}+C = \\frac35x^{5/3}+C$"],
   ans:"(i) $\\frac32x^{2/3}+C$; (j) $-3\\cos\\left(\\frac x3\\right)+C$; (k) $\\frac12e^{2x}+C$; (l) $\\frac35x^{5/3}+C$",
   note:"Parts (j) and (k) use the reverse chain rule, which the lectures had not covered at this point. The official solutions give only the final answers; the working is added here."},
  {id:"CN1-ECP6-a-d", src:"Course notes Ch. 1, End of Chapter Problem 6, parts (a) to (d)", lec:"L04", kind:"chapter", page:"p. 37",
   q:"Evaluate the definite integral.<br>(a) $\\displaystyle\\int_{-1}^32\\,dx$<br>(b) $\\displaystyle\\int_0^2x\\,dx$<br>(c) $\\displaystyle\\int_{-1}^3t\\,dt$<br>(d) $\\displaystyle\\int_1^4\\sqrt x\\,dx$",
   sol:[
    "(a) An antiderivative is $F(x) = 2x$.",
    "$\\int_{-1}^32\\,dx = 2x\\Big|_{-1}^3 = 6-(-2) = 8$",
    "(b) An antiderivative is $F(x) = \\frac12x^2$.",
    "$\\int_0^2x\\,dx = \\frac12x^2\\Big|_0^2 = \\frac12(2)^2-0 = 2$",
    "(c) An antiderivative is $F(t) = \\frac12t^2$.",
    "$\\int_{-1}^3t\\,dt = \\frac12t^2\\Big|_{-1}^3 = \\frac12(3)^2-\\frac12(-1)^2 = 4$",
    "(d) An antiderivative is $F(x) = \\frac23x^{3/2}$.",
    "$\\int_1^4\\sqrt x\\,dx = \\frac23x^{3/2}\\Big|_1^4 = \\frac23(4)^{3/2}-\\frac23(1)^{3/2} = \\frac{16}3-\\frac23 = \\frac{14}3$"],
   ans:"(a) $8$; (b) $2$; (c) $4$; (d) $\\frac{14}{3}$"},
  {id:"CN1-ECP6-e-h", src:"Course notes Ch. 1, End of Chapter Problem 6, parts (e) to (h)", lec:"L04", kind:"chapter", page:"p. 37",
   q:"Evaluate the definite integral.<br>(e) $\\displaystyle\\int_0^xe^t\\,dt$<br>(f) $\\displaystyle\\int_1^2(x^2+1)\\,dx$<br>(g) $\\displaystyle\\int_0^{\\pi/2}\\cos(\\theta)\\,d\\theta$<br>(h) $\\displaystyle\\int_0^\\pi\\sin(2\\theta)\\,d\\theta$",
   sol:[
    "(e) An antiderivative is $F(t) = e^t$.",
    "$\\int_0^xe^t\\,dt = e^t\\Big|_0^x = e^x-e^0 = e^x-1$",
    "(f) An antiderivative is $F(x) = \\frac13x^3+x$.",
    "$\\int_1^2(x^2+1)\\,dx = \\left(\\frac13x^3+x\\right)\\Big|_1^2 = \\left(\\frac83+2\\right)-\\left(\\frac13+1\\right) = \\frac{14}3-\\frac43 = \\frac{10}3$",
    "(g) An antiderivative is $F(\\theta) = \\sin(\\theta)$.",
    "$\\int_0^{\\pi/2}\\cos(\\theta)\\,d\\theta = \\sin(\\theta)\\Big|_0^{\\pi/2} = 1-0 = 1$",
    "(h) An antiderivative is $F(\\theta) = -\\frac12\\cos(2\\theta)$ (check: $F'(\\theta) = -\\frac12(-\\sin(2\\theta))(2) = \\sin(2\\theta)$).",
    "$\\int_0^\\pi\\sin(2\\theta)\\,d\\theta = -\\frac12\\cos(2\\theta)\\Big|_0^\\pi = -\\frac12\\cos(2\\pi)+\\frac12\\cos(0) = -\\frac12+\\frac12 = 0$"],
   ans:"(e) $e^x-1$; (f) $\\frac{10}{3}$; (g) $1$; (h) $0$",
   note:"Part (h) uses the reverse chain rule, which the lectures had not covered at this point."},
  {id:"CN1-ECP6-i", src:"Course notes Ch. 1, End of Chapter Problem 6, part (i)", lec:"L04", kind:"chapter", page:"p. 37",
   q:"Evaluate the definite integral.<br>(i) $\\displaystyle\\int_1^3\\left(\\frac1{x^2}+2x\\right)dx$",
   sol:[
    "(i) An antiderivative is $F(x) = -\\frac1x+x^2$.",
    "$\\int_1^3\\left(\\frac1{x^2}+2x\\right)dx = \\left(-\\frac1x+x^2\\right)\\Big|_1^3 = \\left(-\\frac13+9\\right)-(-1+1) = \\frac{26}3$"],
   ans:"(i) $\\frac{26}{3}$"},
  {id:"CN1-ECP7", src:"Course notes Ch. 1, End of Chapter Problem 7", lec:"L02", kind:"chapter", page:"p. 38",
   q:"Use the differential approximation to approximate the change in $y$.<br>(a) $y = \\sqrt x$ as $x$ changes from $x=4$ to $x=5$<br>(b) $y = \\sqrt x$ as $x$ changes from $x=4$ to $x=3$<br>(c) $y = e^x$ as $x$ changes from $x=0$ to $x=0.3$<br>(d) $y = e^{2x}$ as $x$ changes from $x=0$ to $x=0.3$<br>(e) $y = \\cos(x)$ as $x$ changes from $x=\\frac\\pi4$ to $x=\\frac\\pi5$",
   sol:[
    "(a) $f'(x) = \\dfrac1{2\\sqrt x}$, $a=4$, $\\Delta x = 1$.",
    "$\\Delta y\\approx f'(4)\\Delta x = \\dfrac1{2\\sqrt4}\\cdot1 = \\dfrac14$",
    "(b) $f'(x) = \\dfrac1{2\\sqrt x}$, $a=4$, $\\Delta x = -1$.",
    "$\\Delta y\\approx f'(4)\\Delta x = \\dfrac1{2\\sqrt4}\\cdot(-1) = -\\dfrac14$",
    "(c) $f'(x) = e^x$, $a=0$, $\\Delta x = 0.3$.",
    "$\\Delta y\\approx f'(0)\\Delta x = e^0(0.3) = 0.3$",
    "(d) $f'(x) = 2e^{2x}$, $a=0$, $\\Delta x = 0.3$.",
    "$\\Delta y\\approx f'(0)\\Delta x = 2e^0(0.3) = 0.6$",
    "(e) $f'(x) = -\\sin(x)$, $a = \\frac\\pi4$, $\\Delta x = \\frac\\pi5-\\frac\\pi4 = -\\frac\\pi{20}$.",
    "$\\Delta y\\approx f'\\!\\left(\\frac\\pi4\\right)\\Delta x = -\\frac1{\\sqrt2}\\left(-\\frac\\pi{20}\\right) = \\frac\\pi{20\\sqrt2}$"],
   ans:"(a) $\\frac14$; (b) $-\\frac14$; (c) $0.3$; (d) $0.6$; (e) $\\frac{\\pi}{20\\sqrt2}$"},
  {id:"CN1-ECP8", src:"Course notes Ch. 1, End of Chapter Problem 8", lec:"L03", kind:"chapter", page:"p. 38",
   q:"State the order of the differential equation.<br>(a) $y' = 10-3y$<br>(b) $y''+10y'+y^3 = x^3$<br>(c) $y'+x^2y = x^{-3}$<br>(d) $y''+(y')^3 = 0$<br>(e) $y''' = (xy)^2+1$",
   sol:[
    "(a) The highest derivative of $y$ is $y'$, so the DE is first-order.",
    "(b) The highest derivative of $y$ is $y''$, so the DE is second-order.",
    "(c) The highest derivative of $y$ is $y'$, so the DE is first-order.",
    "(d) The highest derivative of $y$ is $y''$, so the DE is second-order.",
    "(e) The highest derivative of $y$ is $y'''$, so the DE is third-order."],
   ans:"(a) first-order; (b) second-order; (c) first-order; (d) second-order; (e) third-order"},
  {id:"CN1-ECP9", src:"Course notes Ch. 1, End of Chapter Problem 9", lec:"L03", kind:"chapter", page:"p. 38",
   q:"Determine whether the given function is a family of solutions of the differential equation.<br>(a) $y = x^2+C$ for $y' = 2x$<br>(b) $y = -2x+C$ for $y' = 2x+y$<br>(c) $y = -2x-2+Ce^x$ for $y' = 2x+y$<br>(d) $y = x^3+Cx^2$ for $y' = \\dfrac2xy+x^2$<br>(e) $y = \\frac52+Ce^{-2x}$ for $y' = 5-2y$",
   sol:[
    "(a) LHS: $y' = 2x$, which is the RHS. So it is a family of solutions.",
    "(b) LHS: $y' = -2$. RHS: $2x+y = 2x+(-2x+C) = C$.",
    "These are not equal for arbitrary $C$, so it is not a family of solutions.",
    "(c) LHS: $y' = -2+Ce^x$. RHS: $2x+y = 2x+(-2x-2+Ce^x) = -2+Ce^x$.",
    "LHS = RHS, so it is a family of solutions.",
    "(d) LHS: $y' = 3x^2+2Cx$. RHS: $\\frac2x(x^3+Cx^2)+x^2 = 2x^2+2Cx+x^2 = 3x^2+2Cx$.",
    "LHS = RHS, so it is a family of solutions.",
    "(e) LHS: $y' = -2Ce^{-2x}$. RHS: $5-2\\left(\\frac52+Ce^{-2x}\\right) = 5-5-2Ce^{-2x} = -2Ce^{-2x}$.",
    "LHS = RHS, so it is a family of solutions."],
   ans:"(a) solution; (b) not a solution; (c) solution; (d) solution; (e) solution"},
  {id:"CN1-ECP10", src:"Course notes Ch. 1, End of Chapter Problem 10", lec:"L06", kind:"chapter", page:"p. 38",
   q:"Find all solutions of the given differential equation.<br>(a) $y' = 3x^2+x+1$<br>(b) $y' = x^3-5$<br>(c) $y' = x^{1/3}$<br>(d) $y' = x+e^x$<br>(e) $y' = \\cos(2x+1)$<br>(f) $y' = 5\\sin(x)$",
   sol:[
    "(a) $y = \\int(3x^2+x+1)\\,dx = x^3+\\frac12x^2+x+C$",
    "(b) $y = \\int(x^3-5)\\,dx = \\frac14x^4-5x+C$",
    "(c) $y = \\int x^{1/3}\\,dx = \\frac34x^{4/3}+C$",
    "(d) $y = \\int(x+e^x)\\,dx = \\frac12x^2+e^x+C$",
    "(e) By the Chain Rule, $\\frac{d}{dx}\\sin(2x+1) = 2\\cos(2x+1)$, so",
    "$y = \\int\\cos(2x+1)\\,dx = \\frac12\\sin(2x+1)+C$",
    "(f) $y = \\int5\\sin(x)\\,dx = -5\\cos(x)+C$"],
   ans:"(a) $y=x^3+\\frac12x^2+x+C$; (b) $y=\\frac14x^4-5x+C$; (c) $y=\\frac34x^{4/3}+C$; (d) $y=\\frac12x^2+e^x+C$; (e) $y=\\frac12\\sin(2x+1)+C$; (f) $y=-5\\cos(x)+C$",
   note:"Part (e) uses the reverse chain rule, which the lectures had not covered at this point."},
  {id:"CN1-ECP11", src:"Course notes Ch. 1, End of Chapter Problem 11", lec:"L06", kind:"chapter", page:"p. 38",
   q:"Solve the initial value problem.<br>(a) $y' = x+1$, $y(0) = 0$<br>(b) $y' = 2x^2$, $y(1) = 2$<br>(c) $y' = 5$, $y(1) = 2$<br>(d) $y' = x^{-1/4}$, $y(1) = 1$<br>(e) $y' = \\sin(x)$, $y(\\pi) = 1$<br>(f) $y' = 1-3e^x$, $y(0) = 5$",
   sol:[
    "(a) $y = \\int(x+1)\\,dx = \\frac12x^2+x+C$",
    "$y=0$ when $x=0$: $0 = 0+0+C \\Rightarrow C = 0$",
    "$y = \\frac12x^2+x$",
    "(b) $y = \\int2x^2\\,dx = \\frac23x^3+C$",
    "$y=2$ when $x=1$: $2 = \\frac23+C \\Rightarrow C = \\frac43$",
    "$y = \\frac23x^3+\\frac43$",
    "(c) $y = \\int5\\,dx = 5x+C$",
    "$y=2$ when $x=1$: $2 = 5+C \\Rightarrow C = -3$",
    "$y = 5x-3$",
    "(d) $y = \\int x^{-1/4}\\,dx = \\frac43x^{3/4}+C$",
    "$y=1$ when $x=1$: $1 = \\frac43+C \\Rightarrow C = -\\frac13$",
    "$y = \\frac43x^{3/4}-\\frac13$",
    "(e) $y = \\int\\sin(x)\\,dx = -\\cos(x)+C$",
    "$y=1$ when $x=\\pi$: $1 = -\\cos(\\pi)+C = 1+C \\Rightarrow C = 0$",
    "$y = -\\cos(x)$",
    "(f) $y = \\int(1-3e^x)\\,dx = x-3e^x+C$",
    "$y=5$ when $x=0$: $5 = 0-3e^0+C = -3+C \\Rightarrow C = 8$",
    "$y = x-3e^x+8$"],
   ans:"(a) $y=\\frac12x^2+x$; (b) $y=\\frac23x^3+\\frac43$; (c) $y=5x-3$; (d) $y=\\frac43x^{3/4}-\\frac13$; (e) $y=-\\cos(x)$; (f) $y=x-3e^x+8$"},
  {id:"CN1-ECP12", src:"Course notes Ch. 1, End of Chapter Problem 12", lec:"L04", kind:"chapter", page:"p. 38",
   q:"Given $f'(t)$, use a definite integral to find the net change in $f$ from $t=c$ to $t=d$.<br>(a) $f'(t) = 2t+1$, $c=1$, $d=2$<br>(b) $f'(t) = \\dfrac1{\\sqrt t}$, $c=4$, $d=9$<br>(c) $f'(t) = \\sin(2t)$, $c=0$, $d=\\frac\\pi4$<br>(d) $f'(t) = \\dfrac1{t^2}$, $c=1$, $d=2$<br>(e) $f'(t) = e^{3t}$, $c=0$, $d=1$",
   sol:[
    "(a) An antiderivative is $f(t) = t^2+t$.",
    "$\\Delta f = \\int_1^2(2t+1)\\,dt = [2^2+2]-[1^2+1] = 4$",
    "(b) An antiderivative is $f(t) = 2\\sqrt t$.",
    "$\\Delta f = \\int_4^9t^{-1/2}\\,dt = 2\\sqrt9-2\\sqrt4 = 6-4 = 2$",
    "(c) An antiderivative is $f(t) = -\\frac12\\cos(2t)$.",
    "$\\Delta f = \\int_0^{\\pi/4}\\sin(2t)\\,dt = -\\frac12\\cos\\!\\left(\\frac\\pi2\\right)-\\left[-\\frac12\\cos(0)\\right] = 0+\\frac12 = \\frac12$",
    "(d) An antiderivative is $f(t) = -\\frac1t$.",
    "$\\Delta f = \\int_1^2t^{-2}\\,dt = -\\frac12-\\left(-\\frac11\\right) = \\frac12$",
    "(e) An antiderivative is $f(t) = \\frac13e^{3t}$.",
    "$\\Delta f = \\int_0^1e^{3t}\\,dt = \\frac13e^3-\\frac13e^0 = \\frac13e^3-\\frac13$"],
   ans:"(a) $4$; (b) $2$; (c) $\\frac12$; (d) $\\frac12$; (e) $\\frac13e^3-\\frac13$",
   note:"Parts (c) and (e) use the reverse chain rule, which the lectures had not covered at this point."}
]);


